/* 生成的文件，不要手改：node tools/optics-build.mjs 从 tools/optics/ 生成（inputs 899e57c60616cab1，公式由 katex@0.16.11 转成 MathML）。 */
window.MOLASTRIA_OPTICS = {"index":{"title":"光学","sub":"从惠更斯的子波到看见原子","eyebrow":"MOLASTRIA · WAVES, LIGHT AND IMAGES","h1":"光学<span class=\"fs-h1-en\" lang=\"en\">Optics</span>","question":"光从两条缝里穿过，为什么屏上不是两条亮线，而是一排条纹？","lead":"光学是化学实验室里用得最多的物理：每一台光谱仪、每一台显微镜和衍射仪背后都是这里的几条原理。这个栏目从一张“波场水槽”开始：每个开口都是一排惠更斯子波源，把它们的波加起来，单缝、双缝、光栅、圆孔和障碍物后面的图样就都出来了。八章依次讲波和惠更斯–菲涅耳原理、干涉和相干性、衍射、光栅和光谱仪、X 射线晶体衍射、偏振和界面、几何光学，最后是傅里叶光学、成像极限和前沿。十二个演示都在浏览器里当场计算。","scope":"<b>怎么读这些标签。</b> 每一章、每一个要点都标了身份：史实、定理（从麦克斯韦方程或波动方程严格推出）、实验确立、近似（在说明的条件下成立，条件外会失效）、前沿（正在发展，结论可能变）和未解决。光学里很多公式是近似：夫琅禾费衍射要求屏够远，几何光学要求开口远大于波长，Scherrer 公式只对小晶粒成立。标签会说清楚是哪一种。","levels":{"history":["史实","有据可查的历史和文献事实"],"proved":["定理","从麦克斯韦方程或波动方程严格推出"],"tested":["实验确立","有多个独立实验支持，并且是日常使用的技术"],"approx":["近似","在说明的条件下成立，条件之外会失效"],"frontier":["前沿","正在发展，结论和最好的数字还在变"],"open":["未解决","还没有人做到或证明"]},"demoKinds":{"exact":["精确计算","按定义或解析公式当场计算（模型的假设写在每个演示下面）"]},"groups":[{"title":"波动光学的核心","ids":["waves","interference","diffraction","gratings"]},{"title":"光和物质","ids":["xray","polarization"]},{"title":"成像","ids":["geometric","fourier"]}],"chapters":[{"id":"waves","n":"01","title":"光是波：叠加原理和惠更斯–菲涅耳原理","summary":"光是电磁波；波长、频率、相位和复振幅；强度是振幅的平方，所以叠加的是振幅不是亮度。惠更斯–菲涅耳原理把衍射和干涉化成“把子波加起来”，Kirchhoff 给了它数学形式。开头的演示是站长 Fe 的“波的衍射原理与交互动画”。","level":"tested","demos":["tank"]},{"id":"interference","n":"02","title":"干涉与相干性：从杨氏双缝到引力波","summary":"双缝条纹的间距；分波前和分振幅两类干涉仪；薄膜的颜色、增透膜和牛顿环；时间相干和空间相干，相干长度 λ²/Δλ；傅里叶变换光谱；一个一个的光子、电子和 C₆₀ 分子也会干涉；LIGO、光学相干层析。","level":"tested","demos":["film","michelson"]},{"id":"diffraction","n":"03","title":"衍射：单缝、圆孔、泊松亮斑和分辨率的极限","summary":"夫琅禾费单缝图样和它的暗纹；菲涅耳衍射、Cornu 螺线和直边；为什么菲涅耳数决定看到哪一种；圆孔的艾里斑、瑞利判据和眼睛、望远镜、显微镜的分辨率；泊松亮斑的故事、Babinet 原理、波带片和“不衍射”的 Bessel 光束。","level":"tested","demos":["fresnel","airy"]},{"id":"gratings","n":"04","title":"多缝和光栅：把光分成光谱","summary":"N 条缝的干涉因子，主极大和次极大；光栅方程、角色散和分辨本领 R = mN；自由光谱范围、闪耀光栅和中阶梯光栅；Fraunhofer、Rowland 和刻线机；棱镜和光栅的比较；啁啾脉冲放大；光盘和蝴蝶翅膀上的结构色；光谱仪怎样用在化学里。","level":"tested","demos":["grating"]},{"id":"xray","n":"05","title":"X 射线与晶体衍射：用光栅的道理看原子","summary":"1912 年的 Laue 照片和 Bragg 父子的反射定律；三维光栅、倒易格子、Laue 条件和 Ewald 球；结构因子和系统消光；粉末衍射、Scherrer 公式和 Rietveld 精修；相位问题和 Patterson 函数；DNA 的纤维图、肌红蛋白、准晶；X 射线自由电子激光和相干衍射成像。","level":"tested","demos":["bragg","powder"]},{"id":"polarization","n":"06","title":"偏振与界面：光是横波","summary":"光的电场垂直于传播方向，可以朝不同方向振动；菲涅耳公式给出界面上反射和透射多少；布儒斯特角和全反射；Jones 矢量和矩阵，偏振片和波片；圆偏振与手性分子、旋光和圆二色；天空为什么蓝、为什么偏振，Rayleigh 和 Mie 散射；双折射和应力。","level":"proved","demos":["reflect","jones"]},{"id":"geometric","n":"07","title":"几何光学：波长趋于零时的光线","summary":"费马原理和斯涅尔定律；几何光学是波动光学在波长很小时的极限；透镜、成像公式和磨镜者公式；真实透镜的像差：球差、色差和另外几种；数值孔径；光纤的全反射和损耗；光镊用光的动量抓住小颗粒。","level":"approx","demos":["lens"]},{"id":"fourier","n":"08","title":"傅里叶光学、成像与前沿","summary":"透镜做傅里叶变换：Abbe 的显微镜成像理论和分辨率极限；空间滤波、暗场和 Zernike 相衬；全息术；快速傅里叶变换让这一切进了计算机；绕过衍射极限的超分辨荧光显微镜（STED、PALM、STORM）；相干衍射成像；负折射和超材料、光子晶体、轨道角动量光；以及还没有答案的问题。","level":"tested","demos":["abbe"]}],"milestones":[{"year":"1690","text":"Huygens 的《光论》：波前上每一点都是新的子波源（<a href=\"#c-waves\" data-open=\"waves\">01 · 光是波：叠加原理和惠更斯–菲涅耳原理</a>）。"},{"year":"1804","text":"Young 用双缝（和细线、头发）的干涉条纹论证光是波 <span class=\"chm-cites\">[<a href=\"#ref-young1804\" data-ref=\"young1804\">Young 1804</a>]</span>。"},{"year":"1815","text":"Brewster 找到反射光完全偏振的角度 <span class=\"chm-cites\">[<a href=\"#ref-brewster1815\" data-ref=\"brewster1815\">Brewster 1815</a>]</span>。"},{"year":"1818","text":"Fresnel 的衍射论文；Poisson 推出圆盘阴影中心该有亮点来反驳，Arago 当场看到了它（<a href=\"#c-waves\" data-open=\"waves\">01 · 光是波：叠加原理和惠更斯–菲涅耳原理</a>）。"},{"year":"1871","text":"Rayleigh 用 1/λ⁴ 的散射解释天空的蓝色 <span class=\"chm-cites\">[<a href=\"#ref-rayleigh1871\" data-ref=\"rayleigh1871\">Rayleigh 1871</a>]</span>。"},{"year":"1873","text":"Abbe 的显微镜成像理论和分辨率极限 <span class=\"chm-cites\">[<a href=\"#ref-abbe1873\" data-ref=\"abbe1873\">Abbe 1873</a>]</span>。"},{"year":"1879","text":"Rayleigh 的分辨判据和光栅的分辨本领 <span class=\"chm-cites\">[<a href=\"#ref-rayleigh1879\" data-ref=\"rayleigh1879\">Rayleigh 1879</a>]</span>。"},{"year":"1882","text":"Rowland 的凹面光栅和刻线机 <span class=\"chm-cites\">[<a href=\"#ref-rowland1882\" data-ref=\"rowland1882\">Rowland 1882</a>]</span>。"},{"year":"1883","text":"Kirchhoff 给惠更斯–菲涅耳原理一个数学形式 <span class=\"chm-cites\">[<a href=\"#ref-kirchhoff1883\" data-ref=\"kirchhoff1883\">Kirchhoff 1883</a>]</span>；1896 年 Sommerfeld 严格解出半无限屏的衍射 <span class=\"chm-cites\">[<a href=\"#ref-sommerfeld1896\" data-ref=\"sommerfeld1896\">Sommerfeld 1896</a>]</span>。"},{"year":"1887","text":"Michelson 和 Morley 的干涉仪实验没看到“以太风” <span class=\"chm-cites\">[<a href=\"#ref-michelson1887\" data-ref=\"michelson1887\">Michelson &amp; Morley 1887</a>]</span>。"},{"year":"1908","text":"Mie 解出球形粒子的散射，解释胶体金的颜色 <span class=\"chm-cites\">[<a href=\"#ref-mie1908\" data-ref=\"mie1908\">Mie 1908</a>]</span>。"},{"year":"1913","text":"Friedrich、Knipping 和 Laue 的 X 射线衍射照片 <span class=\"chm-cites\">[<a href=\"#ref-laue1913\" data-ref=\"laue1913\">Friedrich, Knipping &amp; Laue 1913</a>]</span>；Bragg 的反射定律 <span class=\"chm-cites\">[<a href=\"#ref-bragg1913\" data-ref=\"bragg1913\">Bragg &amp; Bragg 1913</a>]</span>（<a href=\"#c-xray\" data-open=\"xray\">05 · X 射线与晶体衍射：用光栅的道理看原子</a>）。"},{"year":"1934","text":"Patterson 函数：不要相位，先找原子间的距离矢量 <span class=\"chm-cites\">[<a href=\"#ref-patterson1934\" data-ref=\"patterson1934\">Patterson 1934</a>]</span>。"},{"year":"1938","text":"Zernike 定义相干度 <span class=\"chm-cites\">[<a href=\"#ref-zernike1938\" data-ref=\"zernike1938\">Zernike 1938</a>]</span>；1942 年发表相衬显微镜 <span class=\"chm-cites\">[<a href=\"#ref-zernike1942\" data-ref=\"zernike1942\">Zernike 1942</a>]</span>。"},{"year":"1941","text":"Jones 的偏振矩阵算法 <span class=\"chm-cites\">[<a href=\"#ref-jones1941\" data-ref=\"jones1941\">Jones 1941</a>]</span>。"},{"year":"1948","text":"Gabor 发明全息术 <span class=\"chm-cites\">[<a href=\"#ref-gabor1948\" data-ref=\"gabor1948\">Gabor 1948</a>]</span>。"},{"year":"1953","text":"Franklin 和 Gosling 的 DNA 纤维衍射图 <span class=\"chm-cites\">[<a href=\"#ref-franklin1953\" data-ref=\"franklin1953\">Franklin &amp; Gosling 1953</a>]</span>。"},{"year":"1956","text":"Hanbury Brown 和 Twiss 测光强的关联 <span class=\"chm-cites\">[<a href=\"#ref-hbt1956\" data-ref=\"hbt1956\">Hanbury Brown &amp; Twiss 1956</a>]</span>。"},{"year":"1958","text":"第一个蛋白质（肌红蛋白）的三维结构 <span class=\"chm-cites\">[<a href=\"#ref-kendrew1958\" data-ref=\"kendrew1958\">Kendrew et al. 1958</a>]</span>。"},{"year":"1960","text":"Maiman 的红宝石激光 <span class=\"chm-cites\">[<a href=\"#ref-maiman1960\" data-ref=\"maiman1960\">Maiman 1960</a>]</span>。"},{"year":"1961","text":"Jönsson 的电子双缝干涉 <span class=\"chm-cites\">[<a href=\"#ref-jonsson1961\" data-ref=\"jonsson1961\">Jönsson 1961</a>]</span>；1989 年 Tonomura 看到条纹一个电子一个电子地长出来 <span class=\"chm-cites\">[<a href=\"#ref-tonomura1989\" data-ref=\"tonomura1989\">Tonomura et al. 1989</a>]</span>。"},{"year":"1965","text":"Cooley 和 Tukey 的快速傅里叶变换 <span class=\"chm-cites\">[<a href=\"#ref-cooley1965\" data-ref=\"cooley1965\">Cooley &amp; Tukey 1965</a>]</span>。"},{"year":"1966","text":"高锟和 Hockham 指出光纤损耗来自杂质 <span class=\"chm-cites\">[<a href=\"#ref-kao1966\" data-ref=\"kao1966\">Kao &amp; Hockham 1966</a>]</span>。"},{"year":"1969","text":"Rietveld 用结构模型拟合整张粉末衍射图 <span class=\"chm-cites\">[<a href=\"#ref-rietveld1969\" data-ref=\"rietveld1969\">Rietveld 1969</a>]</span>。"},{"year":"1984","text":"Shechtman 的十次对称衍射图：准晶 <span class=\"chm-cites\">[<a href=\"#ref-shechtman1984\" data-ref=\"shechtman1984\">Shechtman et al. 1984</a>]</span>。"},{"year":"1985","text":"Strickland 和 Mourou 的啁啾脉冲放大 <span class=\"chm-cites\">[<a href=\"#ref-strickland1985\" data-ref=\"strickland1985\">Strickland &amp; Mourou 1985</a>]</span>。"},{"year":"1986","text":"Ashkin 的单光束光镊 <span class=\"chm-cites\">[<a href=\"#ref-ashkin1986\" data-ref=\"ashkin1986\">Ashkin et al. 1986</a>]</span>。"},{"year":"1987","text":"光子晶体的提出 <span class=\"chm-cites\">[<a href=\"#ref-yablonovitch1987\" data-ref=\"yablonovitch1987\">Yablonovitch 1987</a>; <a href=\"#ref-john1987\" data-ref=\"john1987\">John 1987</a>]</span>；无衍射的 Bessel 光束 <span class=\"chm-cites\">[<a href=\"#ref-durnin1987\" data-ref=\"durnin1987\">Durnin et al. 1987</a>]</span>；Hong–Ou–Mandel 双光子干涉 <span class=\"chm-cites\">[<a href=\"#ref-hom1987\" data-ref=\"hom1987\">Hong et al. 1987</a>]</span>。"},{"year":"1991","text":"光学相干层析（OCT）<span class=\"chm-cites\">[<a href=\"#ref-huang1991\" data-ref=\"huang1991\">Huang et al. 1991</a>]</span>。"},{"year":"1992","text":"Allen 等人：光可以带轨道角动量 <span class=\"chm-cites\">[<a href=\"#ref-allen1992\" data-ref=\"allen1992\">Allen et al. 1992</a>]</span>。"},{"year":"1994","text":"Hell 和 Wichmann 提出 STED 超分辨显微镜 <span class=\"chm-cites\">[<a href=\"#ref-hell1994\" data-ref=\"hell1994\">Hell &amp; Wichmann 1994</a>]</span>。"},{"year":"1999","text":"C₆₀ 分子的干涉 <span class=\"chm-cites\">[<a href=\"#ref-arndt1999\" data-ref=\"arndt1999\">Arndt et al. 1999</a>]</span>；相干衍射成像 <span class=\"chm-cites\">[<a href=\"#ref-miao1999\" data-ref=\"miao1999\">Miao et al. 1999</a>]</span>。"},{"year":"2000","text":"“先衍射、后毁坏”的模拟 <span class=\"chm-cites\">[<a href=\"#ref-neutze2000\" data-ref=\"neutze2000\">Neutze et al. 2000</a>]</span>；Pendry 的完美透镜 <span class=\"chm-cites\">[<a href=\"#ref-pendry2000\" data-ref=\"pendry2000\">Pendry 2000</a>]</span>；2001 年微波负折射实验 <span class=\"chm-cites\">[<a href=\"#ref-shelby2001\" data-ref=\"shelby2001\">Shelby et al. 2001</a>]</span>。"},{"year":"2006","text":"PALM <span class=\"chm-cites\">[<a href=\"#ref-betzig2006\" data-ref=\"betzig2006\">Betzig et al. 2006</a>]</span> 和 STORM <span class=\"chm-cites\">[<a href=\"#ref-rust2006\" data-ref=\"rust2006\">Rust et al. 2006</a>]</span>。"},{"year":"2011","text":"X 射线自由电子激光上的飞秒纳米晶体学 <span class=\"chm-cites\">[<a href=\"#ref-chapman2011\" data-ref=\"chapman2011\">Chapman et al. 2011</a>]</span>。"},{"year":"2016","text":"LIGO 的干涉仪探测到引力波 <span class=\"chm-cites\">[<a href=\"#ref-ligo2016\" data-ref=\"ligo2016\">LIGO &amp; Virgo 2016</a>]</span>。"}],"quiz":[{"q":"圆盘挡住一束平行光，阴影的正中心是什么样？","opts":["最暗：光全被挡住了","一个亮点：圆盘边缘各点到中心的光程一样，子波同相叠加","要看圆盘的颜色","只有用激光才有亮点，阳光没有"],"a":1,"why":"这就是 Poisson–Arago 亮点。它要求光有足够的相干性，阳光通过小孔后也能看到。波场水槽演示里选“障碍物”就能看到。","ch":"waves"},{"q":"氦氖激光（632.8 nm）照在缝距 0.25 mm 的双缝上，1 m 外的屏上条纹间距是多少？","opts":["0.25 mm","约 2.5 mm","约 25 mm","约 0.63 mm"],"a":1,"why":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>y</mi><mo>=</mo><mi>λ</mi><mi>L</mi><mi mathvariant=\"normal\">/</mi><mi>d</mi><mo>=</mo><mn>632.8</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>9</mn></mrow></msup><mo>×</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mn>0.25</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mo>=</mo><mn>2.53</mn></mrow></semantics></math> mm。","ch":"interference"},{"q":"一只发光二极管的中心波长 600 nm、线宽 30 nm，它的相干长度大约是多少？","opts":["约 12 μm","约 1 mm","约 30 nm","约 1 m"],"a":0,"why":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">ℓ</mi><mi>c</mi></msub><mo>≈</mo><msup><mi>λ</mi><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mi mathvariant=\"normal\">Δ</mi><mi>λ</mi><mo>=</mo><mo stretchy=\"false\">(</mo><mn>600</mn><mtext> nm</mtext><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mn>30</mn><mtext> nm</mtext><mo>=</mo><mn>12</mn></mrow></semantics></math> μm。所以 LED 照在厚玻璃上看不到干涉，只有很薄的膜（肥皂泡）才有颜色。","ch":"interference"},{"q":"单缝变窄一半，屏上的中央亮纹怎样变？","opts":["变窄一半","宽度不变，只是变暗","变宽一倍","分裂成两条"],"a":2,"why":"第一个暗纹在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>=</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>a</mi></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi></mrow></semantics></math> 减半角度加倍。越窄的缝，光散得越开：这是傅里叶变换的“测不准”。","ch":"diffraction"},{"q":"口径 10 cm 的望远镜在 550 nm 下能分开的最小角距离大约是多少？","opts":["约 0.014″","约 1.4″","约 14″","约 1′"],"a":1,"why":"Rayleigh 判据 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ</mi><mo>=</mo><mn>1.22</mn><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>D</mi><mo>=</mo><mn>1.22</mn><mo>×</mo><mn>550</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>9</mn></mrow></msup><mi mathvariant=\"normal\">/</mi><mn>0.1</mn><mo>=</mo><mn>6.7</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>6</mn></mrow></msup></mrow></semantics></math> rad <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>1.38</mn><mtext>″</mtext></mrow></semantics></math>。","ch":"diffraction"},{"q":"要在一级光谱里分开钠的两条 D 线（589.0 nm 和 589.6 nm），光栅至少要照亮多少条刻线？","opts":["约 100","约 1000","约 10 000","刻线数无关，只看线密度"],"a":1,"why":"分辨本领 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi mathvariant=\"normal\">Δ</mi><mi>λ</mi><mo>=</mo><mi>m</mi><mi>N</mi><mo>≈</mo><mn>589.3</mn><mi mathvariant=\"normal\">/</mi><mn>0.6</mn><mo>=</mo><mn>982</mn></mrow></semantics></math>，一级时 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi><mo>≈</mo><mn>1000</mn></mrow></semantics></math>。","ch":"gratings"},{"q":"面心立方的铜为什么没有 (100) 和 (110) 衍射峰？","opts":["那些晶面上没有原子","晶胞里四个原子的散射在这些方向上正好抵消：h、k、l 有奇有偶时 F = 0","X 射线波长太长","铜吸收了这些方向的 X 射线"],"a":1,"why":"这是面心格子的系统消光，铜的第一个峰是 (111)，在 43.3°（铜靶 Kα）。","ch":"xray"},{"q":"两片正交的偏振片之间插一片轴在 45° 的偏振片，自然光能透过多少？","opts":["0：正交的两片总是全挡","1/2","1/4","1/8"],"a":3,"why":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>×</mo><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mn>45</mn><mi mathvariant=\"normal\">°</mi><mo>×</mo><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mn>45</mn><mi mathvariant=\"normal\">°</mi><mo>=</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mn>8</mn></mrow></semantics></math>。中间那片把偏振投影到 45°，第三片再投影一次。","ch":"polarization"},{"q":"偏振太阳镜为什么能挡掉水面的反光？","opts":["镜片吸收了所有的蓝光","在布儒斯特角附近，水面反射的几乎全是水平偏振，镜片只让竖直偏振通过","反光比直射光的波长长","镜片表面有增透膜"],"a":1,"why":"空气到水的布儒斯特角 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>arctan</mi><mo>⁡</mo><mn>1.333</mn><mo>=</mo><mn>53.1</mn><mi mathvariant=\"normal\">°</mi></mrow></semantics></math>，在这附近 p 偏振（竖直）几乎不反射。","ch":"polarization"},{"q":"同一块平凸透镜聚焦平行光，哪一面朝着光球差小？","opts":["平面朝光","凸面朝光","两种一样","取决于玻璃的颜色"],"a":1,"why":"凸面朝光时两个面分担偏折，每个面的入射角都小，球差约小四倍（光线追迹演示可以对比）。","ch":"geometric"},{"q":"显微镜用 550 nm 的相干光、NA = 0.4 的物镜看一块周期 1.2 μm 的光栅，像里能看到条纹吗？","opts":["能，像只是模糊一点","不能：一级衍射角的正弦 0.46 超过了 NA，只有零级进了物镜，像是一片均匀的亮","能，但颜色会变","要看光栅的材料"],"a":1,"why":"Abbe 极限 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mo>=</mo><mn>1.375</mn></mrow></semantics></math> μm，1.2 μm 比它小。斜照明或油镜能把极限推到更小。","ch":"fourier"},{"q":"STED、PALM 这些超分辨显微镜推翻了 Abbe 的衍射极限吗？","opts":["推翻了：衍射斑可以做得任意小","没有：衍射斑还是那么大，它们让相邻的分子不在同一时刻发光，再逐个定位","没有，它们只是用了更短的波长","推翻了，因为用了量子纠缠"],"a":1,"why":"单个衍射斑的中心可以定到约 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s</mi><mi mathvariant=\"normal\">/</mi><msqrt><mi>N</mi></msqrt></mrow></semantics></math>；关键是开关荧光分子。","ch":"fourier"}],"books":[{"title":"Optics","authors":"Eugene Hecht (Pearson, 5th ed. 2017)","note":"最常用的本科光学教材，图多，从波动、几何到傅里叶光学都有。"},{"title":"Principles of Optics","authors":"Max Born, Emil Wolf (Cambridge University Press, 7th ed. 1999)","note":"经典光学的标准参考书，衍射、相干和偏振都推导得很完整。"},{"title":"Introduction to Fourier Optics","authors":"Joseph W. Goodman (W. H. Freeman, 4th ed. 2017)","note":"第八章的展开版：衍射积分、透镜的傅里叶变换、成像系统和全息。"},{"title":"Fundamentals of Photonics","authors":"Bahaa E. A. Saleh, Malvin Carl Teich (Wiley, 3rd ed. 2019)","note":"从光线、波、电磁到光子，以及光纤、激光和光子晶体，偏工程。"},{"title":"Elements of Modern X-ray Physics","authors":"Jens Als-Nielsen, Des McMorrow (Wiley, 2nd ed. 2011)","note":"第五章的展开版：散射、晶体学、相干衍射和同步辐射，讲得很物理。"},{"title":"The Feynman Lectures on Physics, Vol. I, chapters 26–33","authors":"R. P. Feynman, R. B. Leighton, M. Sands (Caltech, free online)","note":"从最短时间原理讲到干涉、衍射、折射率的起源和偏振，适合先读。"}],"open":[{"q":"可见光波段能不能做出低损耗的负折射材料和真正的“完美透镜”？","ch":"fourier"},{"q":"不用晶体，能不能用 X 射线激光测出单个蛋白质分子的原子结构？","ch":"xray"},{"q":"超分辨显微镜能不能在活细胞里同时做到快、不伤细胞和分子级的分辨率？","ch":"fourier"},{"q":"光子晶体和超表面能在多大程度上替代传统的透镜和棱镜？","ch":"fourier"},{"q":"单个光子的波函数（位置表象）该怎样定义？光子没有通常意义上的位置算符，这仍是讨论中的问题。","ch":"waves"}],"notes":{"map":"每张卡片是一章。标签是这一章主体内容的身份；章里的要点各自另有标签。读过的章会打上记号（只记在这台设备上）。","history":"年份是论文或著作发表的年份。","path":"想接着往下读：谱图馆的<a href=\"../spectra/\">91 种分析方法</a>是这里的原理在实验室里的用法；化学学科馆的<a href=\"../chemistry/structural/#c-diffraction\">衍射与结构解析</a>一章讲晶体结构怎样解出来；量子物理展馆的<a href=\"../quantum/physics/#c-optics\">量子光学</a>讲光子；游乐场里的<a href=\"../qchem/#play-wave\">二维波包画墙</a>可以自己画缝，看量子的波怎样衍射。","library":"共 46 篇。每篇按 DOI 在 OpenAlex（数据来自 Crossref）查过题目、作者、年份和卷号（2026 年 11 月，node tools/optics-refs.mjs 可以重查）。"}},"refs":[{"id":"young1804","authors":"Thomas Young","year":1804,"title":"The Bakerian Lecture: Experiments and calculations relative to physical optics","journal":"Philosophical Transactions of the Royal Society of London","vol":"94","pages":"1–16","doi":"10.1098/rstl.1804.0001","arxiv":"","url":"","note":"","used":["waves","interference"]},{"id":"brewster1815","authors":"David Brewster","year":1815,"title":"On the laws which regulate the polarisation of light by reflexion from transparent bodies","journal":"Philosophical Transactions of the Royal Society of London","vol":"105","pages":"125–159","doi":"10.1098/rstl.1815.0010","arxiv":"","url":"","note":"","used":["polarization"]},{"id":"rayleigh1871","authors":"J. W. Strutt (Lord Rayleigh)","year":1871,"title":"On the light from the sky, its polarization and colour","journal":"The London, Edinburgh, and Dublin Philosophical Magazine and Journal of Science","vol":"41","pages":"107–120","doi":"10.1080/14786447108640452","arxiv":"","url":"","note":"","used":["polarization"]},{"id":"abbe1873","authors":"E. Abbe","year":1873,"title":"Beiträge zur Theorie des Mikroskops und der mikroskopischen Wahrnehmung","journal":"Archiv für Mikroskopische Anatomie","vol":"9","pages":"413–468","doi":"10.1007/BF02956173","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"rayleigh1879","authors":"Lord Rayleigh","year":1879,"title":"Investigations in optics, with special reference to the spectroscope","journal":"The London, Edinburgh, and Dublin Philosophical Magazine and Journal of Science","vol":"8","pages":"261–274","doi":"10.1080/14786447908639684","arxiv":"","url":"","note":"","used":["diffraction","gratings"]},{"id":"rowland1882","authors":"H. A. Rowland","year":1882,"title":"Preliminary notice of the results accomplished in the manufacture and theory of gratings for optical purposes","journal":"The London, Edinburgh, and Dublin Philosophical Magazine and Journal of Science","vol":"13","pages":"469–474","doi":"10.1080/14786448208627217","arxiv":"","url":"","note":"","used":["gratings"]},{"id":"kirchhoff1883","authors":"G. Kirchhoff","year":1883,"title":"Zur Theorie der Lichtstrahlen","journal":"Annalen der Physik","vol":"254","pages":"663–695","doi":"10.1002/andp.18832540409","arxiv":"","url":"","note":"","used":["waves"]},{"id":"michelson1887","authors":"A. A. Michelson, E. W. Morley","year":1887,"title":"On the relative motion of the Earth and the luminiferous ether","journal":"American Journal of Science","vol":"34","pages":"333–345","doi":"10.2475/ajs.s3-34.203.333","arxiv":"","url":"","note":"","used":["interference"]},{"id":"sommerfeld1896","authors":"A. Sommerfeld","year":1896,"title":"Mathematische Theorie der Diffraction","journal":"Mathematische Annalen","vol":"47","pages":"317–374","doi":"10.1007/BF01447273","arxiv":"","url":"","note":"","used":["waves","diffraction"]},{"id":"mie1908","authors":"Gustav Mie","year":1908,"title":"Beiträge zur Optik trüber Medien, speziell kolloidaler Metallösungen","journal":"Annalen der Physik","vol":"330","pages":"377–445","doi":"10.1002/andp.19083300302","arxiv":"","url":"","note":"","used":["polarization"]},{"id":"bragg1913","authors":"William Henry Bragg, William Lawrence Bragg","year":1913,"title":"The reflection of X-rays by crystals","journal":"Proceedings of the Royal Society of London A","vol":"88","pages":"428–438","doi":"10.1098/rspa.1913.0040","arxiv":"","url":"","note":"","used":["xray"]},{"id":"laue1913","authors":"W. Friedrich, P. Knipping, M. Laue","year":1913,"title":"Interferenzerscheinungen bei Röntgenstrahlen","journal":"Annalen der Physik","vol":"346","pages":"971–988","doi":"10.1002/andp.19133461004","arxiv":"","url":"","note":"","used":["xray"]},{"id":"patterson1934","authors":"A. L. Patterson","year":1934,"title":"A Fourier Series Method for the Determination of the Components of Interatomic Distances in Crystals","journal":"Physical Review","vol":"46","pages":"372–376","doi":"10.1103/PhysRev.46.372","arxiv":"","url":"","note":"","used":["xray"]},{"id":"zernike1938","authors":"F. Zernike","year":1938,"title":"The concept of degree of coherence and its application to optical problems","journal":"Physica","vol":"5","pages":"785–795","doi":"10.1016/S0031-8914(38)80203-2","arxiv":"","url":"","note":"","used":["interference"]},{"id":"patterson1939","authors":"A. L. Patterson","year":1939,"title":"The Scherrer Formula for X-Ray Particle Size Determination","journal":"Physical Review","vol":"56","pages":"978–982","doi":"10.1103/PhysRev.56.978","arxiv":"","url":"","note":"","used":["xray"]},{"id":"jones1941","authors":"R. Clark Jones","year":1941,"title":"A New Calculus for the Treatment of Optical Systems. I. Description and Discussion of the Calculus","journal":"Journal of the Optical Society of America","vol":"31","pages":"488–493","doi":"10.1364/JOSA.31.000488","arxiv":"","url":"","note":"","used":["polarization"]},{"id":"zernike1942","authors":"F. Zernike","year":1942,"title":"Phase contrast, a new method for the microscopic observation of transparent objects","journal":"Physica","vol":"9","pages":"686–698","doi":"10.1016/S0031-8914(42)80035-X","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"gabor1948","authors":"D. Gabor","year":1948,"title":"A New Microscopic Principle","journal":"Nature","vol":"161","pages":"777–778","doi":"10.1038/161777a0","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"franklin1953","authors":"Rosalind E. Franklin, R. G. Gosling","year":1953,"title":"Molecular Configuration in Sodium Thymonucleate","journal":"Nature","vol":"171","pages":"740–741","doi":"10.1038/171740a0","arxiv":"","url":"","note":"","used":["xray"]},{"id":"hbt1956","authors":"R. Hanbury Brown, R. Q. Twiss","year":1956,"title":"Correlation between Photons in two Coherent Beams of Light","journal":"Nature","vol":"177","pages":"27–29","doi":"10.1038/177027a0","arxiv":"","url":"","note":"","used":["interference"]},{"id":"kendrew1958","authors":"J. C. Kendrew et al.","year":1958,"title":"A Three-Dimensional Model of the Myoglobin Molecule Obtained by X-Ray Analysis","journal":"Nature","vol":"181","pages":"662–666","doi":"10.1038/181662a0","arxiv":"","url":"","note":"","used":["xray"]},{"id":"maiman1960","authors":"T. H. Maiman","year":1960,"title":"Stimulated Optical Radiation in Ruby","journal":"Nature","vol":"187","pages":"493–494","doi":"10.1038/187493a0","arxiv":"","url":"","note":"","used":["waves"]},{"id":"jonsson1961","authors":"Claus Jönsson","year":1961,"title":"Elektroneninterferenzen an mehreren künstlich hergestellten Feinspalten","journal":"Zeitschrift für Physik","vol":"161","pages":"454–474","doi":"10.1007/BF01342460","arxiv":"","url":"","note":"","used":["interference"]},{"id":"cooley1965","authors":"James W. Cooley, John W. Tukey","year":1965,"title":"An Algorithm for the Machine Calculation of Complex Fourier Series","journal":"Mathematics of Computation","vol":"19","pages":"297–301","doi":"10.1090/S0025-5718-1965-0178586-1","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"kao1966","authors":"K. C. Kao, G. A. Hockham","year":1966,"title":"Dielectric-fibre surface waveguides for optical frequencies","journal":"Proceedings of the Institution of Electrical Engineers","vol":"113","pages":"1151–1158","doi":"10.1049/piee.1966.0189","arxiv":"","url":"","note":"","used":["geometric"]},{"id":"rietveld1969","authors":"H. M. Rietveld","year":1969,"title":"A profile refinement method for nuclear and magnetic structures","journal":"Journal of Applied Crystallography","vol":"2","pages":"65–71","doi":"10.1107/S0021889869006558","arxiv":"","url":"","note":"","used":["xray"]},{"id":"shechtman1984","authors":"D. Shechtman et al.","year":1984,"title":"Metallic Phase with Long-Range Orientational Order and No Translational Symmetry","journal":"Physical Review Letters","vol":"53","pages":"1951–1953","doi":"10.1103/PhysRevLett.53.1951","arxiv":"","url":"","note":"","used":["xray"]},{"id":"strickland1985","authors":"Donna Strickland, Gerard Mourou","year":1985,"title":"Compression of amplified chirped optical pulses","journal":"Optics Communications","vol":"56","pages":"219–221","doi":"10.1016/0030-4018(85)90120-8","arxiv":"","url":"","note":"","used":["gratings"]},{"id":"ashkin1986","authors":"A. Ashkin et al.","year":1986,"title":"Observation of a single-beam gradient force optical trap for dielectric particles","journal":"Optics Letters","vol":"11","pages":"288–290","doi":"10.1364/OL.11.000288","arxiv":"","url":"","note":"","used":["geometric"]},{"id":"durnin1987","authors":"J. Durnin, J. J. Miceli, J. H. Eberly","year":1987,"title":"Diffraction-free beams","journal":"Physical Review Letters","vol":"58","pages":"1499–1501","doi":"10.1103/PhysRevLett.58.1499","arxiv":"","url":"","note":"","used":["diffraction"]},{"id":"hom1987","authors":"C. K. Hong, Z. Y. Ou, L. Mandel","year":1987,"title":"Measurement of subpicosecond time intervals between two photons by interference","journal":"Physical Review Letters","vol":"59","pages":"2044–2046","doi":"10.1103/PhysRevLett.59.2044","arxiv":"","url":"","note":"","used":["interference"]},{"id":"john1987","authors":"Sajeev John","year":1987,"title":"Strong localization of photons in certain disordered dielectric superlattices","journal":"Physical Review Letters","vol":"58","pages":"2486–2489","doi":"10.1103/PhysRevLett.58.2486","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"yablonovitch1987","authors":"Eli Yablonovitch","year":1987,"title":"Inhibited Spontaneous Emission in Solid-State Physics and Electronics","journal":"Physical Review Letters","vol":"58","pages":"2059–2062","doi":"10.1103/PhysRevLett.58.2059","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"tonomura1989","authors":"A. Tonomura et al.","year":1989,"title":"Demonstration of single-electron buildup of an interference pattern","journal":"American Journal of Physics","vol":"57","pages":"117–120","doi":"10.1119/1.16104","arxiv":"","url":"","note":"","used":["interference"]},{"id":"huang1991","authors":"David Huang et al.","year":1991,"title":"Optical Coherence Tomography","journal":"Science","vol":"254","pages":"1178–1181","doi":"10.1126/science.1957169","arxiv":"","url":"","note":"","used":["interference"]},{"id":"allen1992","authors":"L. Allen et al.","year":1992,"title":"Orbital angular momentum of light and the transformation of Laguerre-Gaussian laser modes","journal":"Physical Review A","vol":"45","pages":"8185–8189","doi":"10.1103/PhysRevA.45.8185","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"hell1994","authors":"Stefan W. Hell, Jan Wichmann","year":1994,"title":"Breaking the diffraction resolution limit by stimulated emission: stimulated-emission-depletion fluorescence microscopy","journal":"Optics Letters","vol":"19","pages":"780–782","doi":"10.1364/OL.19.000780","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"arndt1999","authors":"Markus Arndt et al.","year":1999,"title":"Wave–particle duality of C60 molecules","journal":"Nature","vol":"401","pages":"680–682","doi":"10.1038/44348","arxiv":"","url":"","note":"","used":["interference"]},{"id":"miao1999","authors":"Jianwei Miao et al.","year":1999,"title":"Extending the methodology of X-ray crystallography to allow imaging of micrometre-sized non-crystalline specimens","journal":"Nature","vol":"400","pages":"342–344","doi":"10.1038/22498","arxiv":"","url":"","note":"","used":["xray","fourier"]},{"id":"neutze2000","authors":"Richard Neutze et al.","year":2000,"title":"Potential for biomolecular imaging with femtosecond X-ray pulses","journal":"Nature","vol":"406","pages":"752–757","doi":"10.1038/35021099","arxiv":"","url":"","note":"","used":["xray"]},{"id":"pendry2000","authors":"J. B. Pendry","year":2000,"title":"Negative Refraction Makes a Perfect Lens","journal":"Physical Review Letters","vol":"85","pages":"3966–3969","doi":"10.1103/PhysRevLett.85.3966","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"shelby2001","authors":"R. A. Shelby, D. R. Smith, S. Schultz","year":2001,"title":"Experimental Verification of a Negative Index of Refraction","journal":"Science","vol":"292","pages":"77–79","doi":"10.1126/science.1058847","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"betzig2006","authors":"Eric Betzig et al.","year":2006,"title":"Imaging Intracellular Fluorescent Proteins at Nanometer Resolution","journal":"Science","vol":"313","pages":"1642–1645","doi":"10.1126/science.1127344","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"rust2006","authors":"Michael J. Rust, Mark Bates, Xiaowei Zhuang","year":2006,"title":"Sub-diffraction-limit imaging by stochastic optical reconstruction microscopy (STORM)","journal":"Nature Methods","vol":"3","pages":"793–796","doi":"10.1038/nmeth929","arxiv":"","url":"","note":"","used":["fourier"]},{"id":"chapman2011","authors":"Henry N. Chapman et al.","year":2011,"title":"Femtosecond X-ray protein nanocrystallography","journal":"Nature","vol":"470","pages":"73–77","doi":"10.1038/nature09750","arxiv":"","url":"","note":"","used":["xray"]},{"id":"ligo2016","authors":"B. P. Abbott et al. (LIGO Scientific Collaboration and Virgo Collaboration)","year":2016,"title":"Observation of Gravitational Waves from a Binary Black Hole Merger","journal":"Physical Review Letters","vol":"116","pages":"061102","doi":"10.1103/PhysRevLett.116.061102","arxiv":"","url":"","note":"","used":["interference"]}],"chapters":{"waves":{"id":"waves","body":[{"p":"光学里几乎所有“奇怪”的现象，衍射、干涉、偏振、光栅光谱、X 射线晶体学、全息，都来自同一个事实：光是波，而波可以叠加。这一章先把波的语言讲清楚，再介绍贯穿全栏目的一个计算方法：把一道波前上的每一点都当作新的波源，然后把它们发出的子波加起来。下面的波场水槽就是这样算出来的。"},{"demo":"tank"},{"h":"光是电磁波"},{"p":"Maxwell 方程在真空里给出电场和磁场的波动方程，传播速度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c</mi><mo>=</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><msqrt><mrow><msub><mi>μ</mi><mn>0</mn></msub><msub><mi>ε</mi><mn>0</mn></msub></mrow></msqrt><mo>=</mo><mn>299</mn><mtext> </mtext><mn>792</mn><mtext> </mtext><mn>458</mn></mrow></semantics></math> m/s。可见光的波长 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi></mrow></semantics></math> 大约 380 到 750 nm，频率 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν</mi><mo>=</mo><mi>c</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi></mrow></semantics></math> 是 400 到 790 THz；X 射线短一千到一万倍（约 0.01 到 10 nm），红外和微波长得多。它们是同一种波，只是尺度不同。光在介质里慢下来，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mi>c</mi><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow></semantics></math> 是折射率；频率不变，所以波长缩短成 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>n</mi></mrow></semantics></math>。"},{"p":"在很多问题里可以暂时忘掉电场是矢量，只用一个标量 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>u</mi></mrow></semantics></math> 代表某一个场分量。这叫标量波近似，第三章的衍射理论、这一章的演示都用它。忽略的东西（偏振、边界上的电磁条件）在第六章再拿回来。"},{"h":"相位、复振幅和强度"},{"p":"一列单色平面波写成 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>u</mi><mo stretchy=\"false\">(</mo><mi>x</mi><mo separator=\"true\">,</mo><mi>t</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mi>A</mi><mi>cos</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>k</mi><mi>x</mi><mo>−</mo><mi>ω</mi><mi>t</mi><mo>+</mo><mi>φ</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math>，波数 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k</mi><mo>=</mo><mn>2</mn><mi>π</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi></mrow></semantics></math>，角频率 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω</mi><mo>=</mo><mn>2</mn><mi>π</mi><mi>ν</mi></mrow></semantics></math>。括号里的整个角度叫相位。计算时更方便的写法是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>u</mi><mo>=</mo><mrow><mi mathvariant=\"normal\">R</mi><mi mathvariant=\"normal\">e</mi></mrow><mtext> </mtext><mo stretchy=\"false\">[</mo><mi>U</mi><msup><mi>e</mi><mrow><mo>−</mo><mi>i</mi><mi>ω</mi><mi>t</mi></mrow></msup><mo stretchy=\"false\">]</mo></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U</mi><mo>=</mo><mi>A</mi><msup><mi>e</mi><mrow><mi>i</mi><mo stretchy=\"false\">(</mo><mi>k</mi><mi>x</mi><mo>+</mo><mi>φ</mi><mo stretchy=\"false\">)</mo></mrow></msup></mrow></semantics></math> 叫复振幅：振幅是它的模，相位是它的辐角。两列同频率的波叠加，只要把复振幅相加，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U</mi><mo>=</mo><msub><mi>U</mi><mn>1</mn></msub><mo>+</mo><msub><mi>U</mi><mn>2</mn></msub></mrow></semantics></math>。"},{"p":"眼睛、照相机和光电探测器都太慢，跟不上 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><msup><mn>0</mn><mn>15</mn></msup></mrow></semantics></math> Hz 的振荡，它们测的是时间平均的能流，也就是强度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi><mo>∝</mo><mi mathvariant=\"normal\">∣</mi><mi>U</mi><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup></mrow></semantics></math>。于是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi><mo>=</mo><mi mathvariant=\"normal\">∣</mi><msub><mi>U</mi><mn>1</mn></msub><mo>+</mo><msub><mi>U</mi><mn>2</mn></msub><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup><mo>=</mo><msub><mi>I</mi><mn>1</mn></msub><mo>+</mo><msub><mi>I</mi><mn>2</mn></msub><mo>+</mo><mn>2</mn><msqrt><mrow><msub><mi>I</mi><mn>1</mn></msub><msub><mi>I</mi><mn>2</mn></msub></mrow></msqrt><mi>cos</mi><mo>⁡</mo><mi mathvariant=\"normal\">Δ</mi><mi>φ</mi></mrow></semantics></math>。最后一项叫干涉项：两束等强的光，相位差 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>φ</mi><mo>=</mo><mn>0</mn></mrow></semantics></math> 时亮度是一束的四倍，相位差 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>π</mi></mrow></semantics></math> 时是零。光加光可以得到黑暗，这句话就是干涉的全部秘密。"},{"p":"相位差常由光程差 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi></mrow></semantics></math> 带来：<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>φ</mi><mo>=</mo><mn>2</mn><mi>π</mi><mi mathvariant=\"normal\">Δ</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi></mrow></semantics></math>。在介质里走几何长度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">ℓ</mi></mrow></semantics></math> 相当于在真空里走 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mi mathvariant=\"normal\">ℓ</mi></mrow></semantics></math>，所以光程是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∑</mo><msub><mi>n</mi><mi>i</mi></msub><msub><mi mathvariant=\"normal\">ℓ</mi><mi>i</mi></msub></mrow></semantics></math>。演示里“光程差”一项就是选中的点到两道缝（或缝的两边）的距离之差，以波长为单位。"},{"h":"惠更斯、菲涅耳和 Kirchhoff"},{"p":"惠更斯在 1690 年提出：波前上的每一点都是一个次级波源，下一时刻的波前是这些子波的包络。这能解释反射和折射，但解释不了为什么光大体上直线传播、为什么会有暗纹。1818 年菲涅耳补上了关键的一步：子波不只是取包络，而是带着各自的相位叠加，互相干涉。这样，直线传播是因为偏离的方向上子波彼此抵消，衍射条纹是因为没有抵消干净。"},{"p":"在这之前，Young 在 1804 年的贝克讲座里已经用两个小孔的干涉条纹论证了光的波动性，并且用条纹间距估出了各种颜色的波长 <span class=\"chm-cites\">[<a href=\"#ref-young1804\" data-ref=\"young1804\">Young 1804</a>]</span>。1882 到 1883 年 Kirchhoff 从波动方程和 Green 定理出发，把菲涅耳的说法写成一个积分 <span class=\"chm-cites\">[<a href=\"#ref-kirchhoff1883\" data-ref=\"kirchhoff1883\">Kirchhoff 1883</a>]</span>：开口里的场当作入射波，挡住的地方当作零，每个点源的贡献是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e</mi><mrow><mi>i</mi><mi>k</mi><mi>r</mi></mrow></msup><mi mathvariant=\"normal\">/</mi><mi>r</mi></mrow></semantics></math> 乘一个倾斜因子 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>cos</mi><mo>⁡</mo><mi>θ</mi><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mn>2</mn></mrow></semantics></math>。这正是演示里那个求和。"},{"note":"<b>Kirchhoff 的边界条件自相矛盾。</b> 同时规定场和它的法向导数在屏上为零，在数学上意味着场处处为零。它好用，是因为缝比波长宽得多时误差很小。1896 年 Sommerfeld 对一个无限薄、理想导电的半平面严格解出了衍射 <span class=\"chm-cites\">[<a href=\"#ref-sommerfeld1896\" data-ref=\"sommerfeld1896\">Sommerfeld 1896</a>]</span>，这是少数几个精确解之一；今天缝宽接近波长时就直接数值解 Maxwell 方程。","kind":"warn"},{"h":"在水槽里看什么"},{"list":["<b>窄缝（a &lt; λ）</b>：缝本身只剩“一个”子波源，出去的几乎是圆形波，光往各个方向都走。这就是衍射最纯粹的样子。","<b>宽缝（a ≫ λ）</b>：中间一大片子波彼此同相，形成一束直直前进的光，几何阴影的边界清楚；只在边缘附近有细细的条纹。几何光学就是这个极限（第七章）。","<b>双缝</b>：两束衍射波重叠的地方，出现亮暗相间的条纹，间隔是 λ/d（以 sin θ 计）。这是第二章的主角。","<b>多缝</b>：缝越多，亮纹越细、越亮，中间的次级亮纹越弱，光栅就是这样把不同颜色分开的（第四章）。","<b>挡板</b>：几何上应当最黑的阴影正中央，反而有一条亮线。三维里一个圆盘后面的这个亮点叫泊松亮斑（第三章）。"]},{"p":"矢量图把“叠加”变成了几何：每一段子波是一支小箭头，长度是它的振幅，方向是它的相位；首尾相接，从起点到终点那一支就是合振幅。暗纹处小箭头绕成一个闭合的圆，亮纹处排成一条近似的直线。很多结论直接从这张图读出来，比如单缝的第一暗纹：缝两边到达的光程差正好一个波长时，小箭头恰好绕一整圈。"},{"h":"近场和远场"},{"p":"离缝近的地方，到缝上不同点的距离差不是角度的简单函数，图样随距离变化，叫菲涅耳衍射；离得足够远（或者在透镜的焦面上），每个点只由一个方向决定，图样只随角度变化，叫夫琅禾费衍射。分界由菲涅耳数 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>F</mi></msub><mo>=</mo><msup><mi>w</mi><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>λ</mi><mi>z</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math> 决定，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>w</mi></mrow></semantics></math> 是开口的半宽、<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z</mi></mrow></semantics></math> 是距离。演示里的水槽只有 14 μm 长，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>F</mi></msub></mrow></semantics></math> 不算小，所以屏上的实线和远场公式（虚线）并不重合；勾上“透镜焦面”就看到干净的远场图样。第三章专门讲这个过渡。"},{"p":"衍射和干涉其实是同一件事：都是把子波的复振幅加起来。习惯上，少数几束光（两束、几束）叠加叫干涉，连续分布的无数子波叠加叫衍射。Feynman 在讲义里说，从来没有人能令人满意地说清两者的区别。"},{"h":"相干和激光"},{"p":"干涉条纹要稳定，两束光的相位差就得在测量的时间里保持不变。普通光源里无数原子各自独立地、每隔几纳秒就重新开始发光，两盏灯之间的相位差乱跳，条纹一闪而过，看不见。所以 Young 让同一束光穿过两个小孔，两路光来自同一个波前，相位差才固定。1960 年 Maiman 做出第一台（红宝石）激光器 <span class=\"chm-cites\">[<a href=\"#ref-maiman1960\" data-ref=\"maiman1960\">Maiman 1960</a>]</span>，从此有了单色、方向集中、相干长度可达米甚至千米的光源，干涉成了日常工具。相干性的定量说法在第二章。"}],"points":[{"h":"叠加的是复振幅，测到的是强度","p":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi><mo>=</mo><mi mathvariant=\"normal\">∣</mi><msub><mi>U</mi><mn>1</mn></msub><mo>+</mo><msub><mi>U</mi><mn>2</mn></msub><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup></mrow></semantics></math> 里的交叉项让“光加光”可以变暗。只要介质是线性的（光不太强），叠加原理就严格成立。","st":"tested"},{"h":"惠更斯–菲涅耳原理","p":"把波前上每一点当作子波源、带相位地叠加，就能算出衍射和干涉。它是从波动方程推出的一个积分表示，不是额外的假设。","st":"proved"},{"h":"Kirchhoff 近似","p":"开口里取入射场、屏后取零，加倾斜因子 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>cos</mi><mo>⁡</mo><mi>θ</mi><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mn>2</mn></mrow></semantics></math>。开口远大于波长时误差很小；接近波长时要解 Maxwell 方程。","st":"approx"},{"h":"衍射和干涉是同一回事","p":"都是子波叠加；少数几束叫干涉，连续分布叫衍射，只是习惯叫法。","st":"proved"},{"h":"菲涅耳数决定近场还是远场","p":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>F</mi></msub><mo>=</mo><msup><mi>w</mi><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>λ</mi><mi>z</mi><mo stretchy=\"false\">)</mo><mo>≫</mo><mn>1</mn></mrow></semantics></math>：几何阴影加边缘条纹；<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>F</mi></msub><mo>≪</mo><mn>1</mn></mrow></semantics></math>：夫琅禾费图样，只随角度变化。","st":"approx"},{"h":"Young 1804：光是波","p":"两孔干涉条纹，加上用条纹间距估出的波长，是光的波动说最早的定量证据之一。","st":"history"}],"math":[{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msup><mi mathvariant=\"normal\">∇</mi><mn>2</mn></msup><mi>u</mi><mo>−</mo><mfrac><msup><mi>n</mi><mn>2</mn></msup><msup><mi>c</mi><mn>2</mn></msup></mfrac><mfrac><mrow><msup><mi mathvariant=\"normal\">∂</mi><mn>2</mn></msup><mi>u</mi></mrow><mrow><mi mathvariant=\"normal\">∂</mi><msup><mi>t</mi><mn>2</mn></msup></mrow></mfrac><mo>=</mo><mn>0</mn><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>u</mi><mo>=</mo><mrow><mi mathvariant=\"normal\">R</mi><mi mathvariant=\"normal\">e</mi></mrow><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">[</mo><mi>U</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"bold\">r</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><msup><mi>e</mi><mrow><mo>−</mo><mi>i</mi><mi>ω</mi><mi>t</mi></mrow></msup><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">]</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msup><mi mathvariant=\"normal\">∇</mi><mn>2</mn></msup><mi>U</mi><mo>+</mo><msup><mi>k</mi><mn>2</mn></msup><msup><mi>n</mi><mn>2</mn></msup><mi>U</mi><mo>=</mo><mn>0</mn></mrow></semantics></math>","cap":"标量波动方程和它的单色形式（Helmholtz 方程），k = 2π/λ。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi mathvariant=\"normal\">∣</mi><msub><mi>U</mi><mn>1</mn></msub><mo>+</mo><msub><mi>U</mi><mn>2</mn></msub><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup><mo>=</mo><msub><mi>I</mi><mn>1</mn></msub><mo>+</mo><msub><mi>I</mi><mn>2</mn></msub><mo>+</mo><mn>2</mn><msqrt><mrow><msub><mi>I</mi><mn>1</mn></msub><msub><mi>I</mi><mn>2</mn></msub></mrow></msqrt><mtext> </mtext><mi>cos</mi><mo>⁡</mo><mi mathvariant=\"normal\">Δ</mi><mi>φ</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi mathvariant=\"normal\">Δ</mi><mi>φ</mi><mo>=</mo><mfrac><mrow><mn>2</mn><mi>π</mi></mrow><mi>λ</mi></mfrac><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi></mrow></semantics></math>","cap":"两束光的干涉；Δ 是光程差。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>U</mi><mo stretchy=\"false\">(</mo><mi>P</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mfrac><mn>1</mn><mrow><mi>i</mi><mi>λ</mi></mrow></mfrac><msub><mo>∬</mo><mi mathvariant=\"script\">A</mi></msub><msub><mi>U</mi><mn>0</mn></msub><mo stretchy=\"false\">(</mo><mi>Q</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><mfrac><msup><mi>e</mi><mrow><mi>i</mi><mi>k</mi><mi>r</mi></mrow></msup><mi>r</mi></mfrac><mtext> </mtext><mfrac><mrow><mn>1</mn><mo>+</mo><mi>cos</mi><mo>⁡</mo><mi>θ</mi></mrow><mn>2</mn></mfrac><mtext> </mtext><mi mathvariant=\"normal\">d</mi><mi>S</mi></mrow></semantics></math>","cap":"Kirchhoff 的衍射积分（三维，𝒜 是开口）<span class=\"chm-cites\">[<a href=\"#ref-kirchhoff1883\" data-ref=\"kirchhoff1883\">Kirchhoff 1883</a>]</span>；二维的演示里 e^{ikr}/r 换成 e^{i(kr − π/4)}/√(λr)。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>N</mi><mi>F</mi></msub><mo>=</mo><mfrac><msup><mi>w</mi><mn>2</mn></msup><mrow><mi>λ</mi><mi>z</mi></mrow></mfrac></mrow></semantics></math>","cap":"菲涅耳数：w 是开口的半宽（或半径），z 是到观察屏的距离。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>v</mi><mo>=</mo><mfrac><mi>c</mi><mi>n</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>λ</mi><mi>n</mi></msub><mo>=</mo><mfrac><mi>λ</mi><mi>n</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>L</mi><mrow><mi mathvariant=\"normal\">o</mi><mi mathvariant=\"normal\">p</mi><mi mathvariant=\"normal\">t</mi></mrow></msub><mo>=</mo><munder><mo>∑</mo><mi>i</mi></munder><msub><mi>n</mi><mi>i</mi></msub><msub><mi mathvariant=\"normal\">ℓ</mi><mi>i</mi></msub></mrow></semantics></math>","cap":"介质里的速度、波长和光程 L_opt。"}],"example":{"q":"演示里的默认参数：绿光 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mo>=</mo><mn>532</mn></mrow></semantics></math> nm，缝宽 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mo>=</mo><mn>1.8</mn></mrow></semantics></math> μm，接收屏在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi><mo>=</mo><mn>14</mn></mrow></semantics></math> μm。(a) 远场的第一暗纹在什么角度？(b) 菲涅耳数是多少，屏上的图样该像远场吗？(c) 换成 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mo>=</mo><mn>0.4</mn></mrow></semantics></math> μm 会怎样？","steps":["(a) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mn>1</mn></msub><mo>=</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>a</mi><mo>=</mo><mn>0.532</mn><mi mathvariant=\"normal\">/</mi><mn>1.8</mn><mo>=</mo><mn>0.296</mn></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mn>1</mn></msub><mo>≈</mo><mn>17.2</mn><mi mathvariant=\"normal\">°</mi></mrow></semantics></math>。","(b) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>F</mi></msub><mo>=</mo><mo stretchy=\"false\">(</mo><mi>a</mi><mi mathvariant=\"normal\">/</mi><mn>2</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>λ</mi><mi>x</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mn>0.81</mn><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mn>0.532</mn><mo>×</mo><mn>14</mn><mo stretchy=\"false\">)</mo><mo>≈</mo><mn>0.11</mn></mrow></semantics></math>。比 1 小，但不是远小于 1：大体像远场，细节（暗纹没有完全到零、位置稍偏）有差别。","(c) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>a</mi><mo>=</mo><mn>1.33</mn><mo>&gt;</mo><mn>1</mn></mrow></semantics></math>：任何角度都满足不了 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>=</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>a</mi></mrow></semantics></math>，没有暗纹；缝像一个点源，出射近似圆形波。"],"a":"在演示里依次点“窄缝”预设和勾上“透镜焦面”，读数里的“第一暗纹”和菲涅耳数就是这几个数。"},"cites":"<a href=\"#ref-young1804\" data-ref=\"young1804\">Young 1804</a> · <a href=\"#ref-kirchhoff1883\" data-ref=\"kirchhoff1883\">Kirchhoff 1883</a> · <a href=\"#ref-sommerfeld1896\" data-ref=\"sommerfeld1896\">Sommerfeld 1896</a> · <a href=\"#ref-maiman1960\" data-ref=\"maiman1960\">Maiman 1960</a>"},"interference":{"id":"interference","body":[{"p":"第一章说，两束光叠加时强度里多出一个干涉项 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><msqrt><mrow><msub><mi>I</mi><mn>1</mn></msub><msub><mi>I</mi><mn>2</mn></msub></mrow></msqrt><mi>cos</mi><mo>⁡</mo><mi mathvariant=\"normal\">Δ</mi><mi>φ</mi></mrow></semantics></math>。这一章讲怎样做出稳定的两束光，怎样读出它们的相位差，以及“稳定”这件事本身可以怎样定量：相干性。干涉是光学里最灵敏的测量手段，可以测出比原子核还小的长度变化。"},{"h":"杨氏双缝"},{"p":"两条相距 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow></semantics></math> 的窄缝被同一束光照亮，在远处距离 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi></mrow></semantics></math> 的屏上，到两缝的光程差是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>≈</mo><mi>d</mi><mtext> </mtext><mi>y</mi><mi mathvariant=\"normal\">/</mi><mi>L</mi></mrow></semantics></math>。光程差是整数个波长时相长，于是亮纹位于 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y</mi><mi>m</mi></msub><mo>=</mo><mi>m</mi><mi>λ</mi><mi>L</mi><mi mathvariant=\"normal\">/</mi><mi>d</mi></mrow></semantics></math>，相邻亮纹的间距 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>y</mi><mo>=</mo><mi>λ</mi><mi>L</mi><mi mathvariant=\"normal\">/</mi><mi>d</mi></mrow></semantics></math>。缝距越小、波长越长，条纹越宽。Young 正是反过来用条纹间距量出了光的波长 <span class=\"chm-cites\">[<a href=\"#ref-young1804\" data-ref=\"young1804\">Young 1804</a>]</span>：红光约 0.7 μm，紫光约 0.4 μm，和今天的数值相差不大。"},{"p":"每条缝本身也有宽度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi></mrow></semantics></math>，所以双缝图样是“单缝衍射的包络”乘“双缝干涉的条纹”。当 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mi mathvariant=\"normal\">/</mi><mi>a</mi></mrow></semantics></math> 是整数时，某些干涉亮纹恰好落在单缝的暗纹上而消失，叫缺级。波场水槽的“缺级：d = 2a”预设里，第 ±2 级不见了。"},{"h":"两类干涉仪"},{"p":"要得到两束相干的光，只有两种办法。一是<b>分波前</b>：从同一道波前上取两块，比如双缝、Lloyd 镜、菲涅耳双棱镜。二是<b>分振幅</b>：用半透半反的表面把一束光的振幅分成两份，让它们各走一路再合起来，比如薄膜、迈克耳孙、Mach–Zehnder 和 Fabry–Perot 干涉仪。后一类能用大面积的扩展光源，所以条纹亮得多，精密测量几乎都用它。"},{"h":"薄膜：肥皂泡、油膜和增透膜"},{"p":"一层厚 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow></semantics></math>、折射率 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow></semantics></math> 的透明膜，上下两个表面的反射光之间多走了 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>n</mi><mi>d</mi><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>t</mi></msub></mrow></semantics></math>（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mi>t</mi></msub></mrow></semantics></math> 是膜内的折射角）。此外还要看两次反射的符号：从光疏射向光密的反射，振幅反射系数为负，相当于多了半个波长（“半波损失”）。肥皂膜两边都是空气，上表面有这个负号、下表面没有，所以极薄（远小于波长）的肥皂膜两束反射光正好抵消，看起来是黑的；肥皂泡快破的时候顶上那一片黑，就是这个原因。"},{"p":"白光照射时，每个波长按自己的相位差相长或相消，剩下的颜色就是膜的颜色，随厚度一圈圈变化。演示里的色带是从 0 到 1500 nm 的“肥皂膜颜色表”：薄时是灰白、黄、品红、蓝，越往厚处颜色越淡，因为好几个波长同时相长，混成接近白色。"},{"p":"增透膜把这件事反过来用。在折射率 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>s</mi></msub></mrow></semantics></math> 的玻璃上镀一层 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mi>f</mi></msub><mo>=</mo><msqrt><msub><mi>n</mi><mi>s</mi></msub></msqrt></mrow></semantics></math>、光学厚度为 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mn>4</mn></mrow></semantics></math> 的膜，两次反射都有半波损失、多走的路程是半个波长，正好抵消。MgF₂（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>≈</mo><mn>1.38</mn></mrow></semantics></math>）不完全满足 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mn>1.52</mn></msqrt><mo>=</mo><mn>1.23</mn></mrow></semantics></math>，但已经把 550 nm 处的反射从 4.3 % 降到约 1.3 %。照相机镜头上那层淡紫色，就是绿光被减掉之后、红和蓝剩下的反光。反过来，高低折射率交替的多层 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mn>4</mn></mrow></semantics></math> 膜可以反射 99.9 % 以上，激光器的腔镜就是这样做的。"},{"demo":"film"},{"p":"把一块微凸的透镜压在平玻璃上，两者之间的空气隙从中心向外慢慢变厚，单色光下看到一圈圈同心的亮暗环，叫牛顿环；中心是暗的（空气隙为零，只剩半波损失）。第 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow></semantics></math> 个暗环的半径 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>m</mi></msub><mo>=</mo><msqrt><mrow><mi>m</mi><mi>λ</mi><mi>R</mi></mrow></msqrt></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow></semantics></math> 是透镜的曲率半径。光学车间至今用这种“干涉样板”检验表面是否平整，误差小于十分之一个波长。"},{"h":"迈克耳孙干涉仪和时间相干性"},{"p":"迈克耳孙干涉仪用一块分束镜把光分到两条互相垂直的臂上，两面镜子把它们反射回来再合并。移动一面镜子 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mn>2</mn></mrow></semantics></math>，光程差变一个波长，条纹移过一条。1887 年 Michelson 和 Morley 用它寻找地球相对“以太”的运动，预期的条纹移动是 0.4 条，结果小于它的二十分之一 <span class=\"chm-cites\">[<a href=\"#ref-michelson1887\" data-ref=\"michelson1887\">Michelson &amp; Morley 1887</a>]</span>。这个零结果后来成为狭义相对论的重要实验背景。"},{"p":"光程差越来越大，条纹会越来越模糊，最后消失。原因是真实的光不是严格单色的：谱宽 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>ν</mi></mrow></semantics></math> 的光，各个频率成分的条纹在光程差约 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>c</mi><mi mathvariant=\"normal\">/</mi><mi mathvariant=\"normal\">Δ</mi><mi>ν</mi></mrow></semantics></math> 之后彼此错开、平均掉。这个长度叫相干长度，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">ℓ</mi><mi>c</mi></msub><mo>≈</mo><msup><mi>λ</mi><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mi mathvariant=\"normal\">Δ</mi><mi>λ</mi></mrow></semantics></math>。白光只有约 1 μm，绿色 LED 约 8 μm，钠灯的一条谱线约几厘米，稳频的单模激光可以到几百米。条纹可见度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V</mi><mo>=</mo><mo stretchy=\"false\">(</mo><msub><mi>I</mi><mi>max</mi><mo>⁡</mo></msub><mo>−</mo><msub><mi>I</mi><mi>min</mi><mo>⁡</mo></msub><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><msub><mi>I</mi><mi>max</mi><mo>⁡</mo></msub><mo>+</mo><msub><mi>I</mi><mi>min</mi><mo>⁡</mo></msub><mo stretchy=\"false\">)</mo></mrow></semantics></math> 随光程差的变化，正是光源光谱的傅里叶变换（Wiener–Khinchin 定理）。"},{"demo":"michelson"},{"p":"这一条把干涉仪变成了光谱仪。扫动一面镜子、记下光强随光程差的变化（干涉图），再做傅里叶变换就得到光谱，光谱分辨率约等于 1/最大光程差（以波数计）。这就是傅里叶变换红外光谱（FTIR）：一次测全部波长（Fellgett 优势），而且没有狭缝挡光（Jacquinot 优势）。今天化学实验室里的红外光谱仪几乎都是这种，见<a href=\"../spectra/#m-ir\">谱图馆 · 红外光谱</a>。"},{"h":"空间相干性"},{"p":"时间相干性问的是同一点上前后两个时刻的相位关系，空间相干性问的是同一时刻两个横向分开的点之间的相位关系。一个张角为 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mi>s</mi></msub></mrow></semantics></math> 的非相干光源，在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><msub><mi>θ</mi><mi>s</mi></msub></mrow></semantics></math> 这么宽的范围内大致是相干的。van Cittert（1934）和 Zernike（1938）证明，光源远处的相干度分布正是光源强度分布的傅里叶变换 <span class=\"chm-cites\">[<a href=\"#ref-zernike1938\" data-ref=\"zernike1938\">Zernike 1938</a>]</span>。所以 Young 的双缝要先让光穿过一个小孔：小孔让光源的张角变小、相干范围变宽，双缝才落在同一个相干区里。"},{"p":"这个定理也能反过来用：测相干度随两点距离的变化，就能推出光源的大小。1920 年 Michelson 和 Pease 用威尔逊山 2.5 m 望远镜上的一副 6 m 长的干涉臂，测出了参宿四的角直径，约 0.047 角秒，是第一次直接量出太阳以外一颗恒星的大小。今天的甚长基线射电干涉（事件视界望远镜拍下的黑洞阴影）用的还是这个原理。"},{"p":"1956 年 Hanbury Brown 和 Twiss 发现，不用比较相位，只比较两个探测器上光强的涨落，也能测出空间相干性 <span class=\"chm-cites\">[<a href=\"#ref-hbt1956\" data-ref=\"hbt1956\">Hanbury Brown &amp; Twiss 1956</a>]</span>。这个“强度干涉”后来引出了量子光学：热光的光子倾向于成团到达（聚束），激光的光子随机到达，而单光子源的光子彼此回避（反聚束）。1987 年 Hong、Ou 和 Mandel 让两个完全相同的光子同时射到分束镜的两边，它们总是从同一边出去，两边各探测到一个的符合计数降到零附近 <span class=\"chm-cites\">[<a href=\"#ref-hom1987\" data-ref=\"hom1987\">Hong et al. 1987</a>]</span>，这是经典波动光学解释不了的双光子干涉。"},{"h":"一个一个地干涉"},{"p":"把光调得极弱，弱到装置里同一时刻最多只有一个光子，长时间曝光后条纹照样出现（G. I. Taylor 1909 年的实验）。电子也一样：1961 年 Jönsson 用人工刻出的多条细缝做出了电子的双缝和多缝干涉 <span class=\"chm-cites\">[<a href=\"#ref-jonsson1961\" data-ref=\"jonsson1961\">Jönsson 1961</a>]</span>；1989 年 Tonomura 等人用电子双棱镜一个一个地记录电子，屏上先是随机的亮点，几万个之后条纹逐渐显现 <span class=\"chm-cites\">[<a href=\"#ref-tonomura1989\" data-ref=\"tonomura1989\">Tonomura et al. 1989</a>]</span>。1999 年，有 60 个碳原子的富勒烯分子 C₆₀ 穿过光栅也产生了干涉 <span class=\"chm-cites\">[<a href=\"#ref-arndt1999\" data-ref=\"arndt1999\">Arndt et al. 1999</a>]</span>。每一个粒子都“和自己干涉”，落在哪里是随机的，但概率由波的强度决定，这就是量子力学的玻恩规则，见<a href=\"../quantum/physics/#c-wave\">量子物理 · 波函数</a>。"},{"h":"今天的干涉仪"},{"p":"2015 年 9 月，LIGO 两台臂长 4 km 的迈克耳孙干涉仪（加上 Fabry–Perot 腔把光程放大几百倍）记录到两个黑洞并合发出的引力波 <span class=\"chm-cites\">[<a href=\"#ref-ligo2016\" data-ref=\"ligo2016\">LIGO &amp; Virgo 2016</a>]</span>：峰值应变约 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>21</mn></mrow></msup></mrow></semantics></math>，相当于 4 km 的臂长变了约 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>4</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>18</mn></mrow></msup></mrow></semantics></math> m，约为质子直径的四百分之一。医学里的光学相干层析（OCT）走另一个极端：故意用相干长度只有几微米的宽谱光，只有光程差小于相干长度的那一层组织才产生条纹，于是可以一层层地“切”出视网膜的断面像 <span class=\"chm-cites\">[<a href=\"#ref-huang1991\" data-ref=\"huang1991\">Huang et al. 1991</a>]</span>。"}],"points":[{"h":"条纹间距 Δy = λL/d","p":"双缝条纹是单缝包络乘干涉条纹；d/a 为整数时缺级。Young 用它量出了光的波长。","st":"tested"},{"h":"半波损失决定薄膜是亮还是黑","p":"从光疏到光密的反射振幅变号。极薄的肥皂膜因此发黑；<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mn>4</mn></mrow></semantics></math> 增透膜的两次反射正好抵消。","st":"tested"},{"h":"相干长度 ≈ λ²/Δλ","p":"谱越窄，条纹能保持的光程差越大。可见度随光程差的变化是光谱的傅里叶变换：FTIR 光谱仪就是这样工作的。","st":"proved"},{"h":"van Cittert–Zernike 定理","p":"远处的空间相干度是光源强度分布的傅里叶变换。所以要先用小孔“造”出相干光，也能反过来测恒星的角直径。","st":"proved"},{"h":"单个粒子也干涉","p":"光子、电子、C₆₀ 分子一次一个地通过，长时间累积出条纹。落点随机，概率由波的强度给出。","st":"tested"},{"h":"双光子干涉没有经典解释","p":"Hong–Ou–Mandel 凹陷：两个全同光子同时进分束镜，总是一起出去。经典波的符合计数凹陷最多到一半。","st":"tested"},{"h":"宏观物体的干涉","p":"干涉实验用的分子已经超过两万个原子质量单位；更大的物体还能不能显出干涉，是检验量子力学和引力怎样相处的一条路。","st":"frontier"}],"math":[{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>y</mi><mo>=</mo><mfrac><mrow><mi>λ</mi><mi>L</mi></mrow><mi>d</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>I</mi><mo stretchy=\"false\">(</mo><mi>θ</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msub><mi>I</mi><mn>0</mn></msub><mtext> </mtext><msup><mrow><mi mathvariant=\"normal\">s</mi><mi mathvariant=\"normal\">i</mi><mi mathvariant=\"normal\">n</mi><mi mathvariant=\"normal\">c</mi></mrow><mn>2</mn></msup><mtext> ⁣</mtext><mo fence=\"true\" stretchy=\"true\" minsize=\"1.8em\" maxsize=\"1.8em\">(</mo><mfrac><mrow><mi>π</mi><mi>a</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow><mi>λ</mi></mfrac><mo fence=\"true\" stretchy=\"true\" minsize=\"1.8em\" maxsize=\"1.8em\">)</mo><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mtext> ⁣</mtext><mo fence=\"true\" stretchy=\"true\" minsize=\"1.8em\" maxsize=\"1.8em\">(</mo><mfrac><mrow><mi>π</mi><mi>d</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow><mi>λ</mi></mfrac><mo fence=\"true\" stretchy=\"true\" minsize=\"1.8em\" maxsize=\"1.8em\">)</mo></mrow></semantics></math>","cap":"双缝条纹间距和远场图样（单缝包络 × 双缝条纹）。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mn>2</mn><msub><mi>n</mi><mi>f</mi></msub><mi>d</mi><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>t</mi></msub><mo>=</mo><mi>m</mi><mi>λ</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>n</mi><mi>f</mi></msub><mo>=</mo><msqrt><mrow><msub><mi>n</mi><mn>0</mn></msub><msub><mi>n</mi><mi>s</mi></msub></mrow></msqrt><mo separator=\"true\">,</mo><mtext>  </mtext><msub><mi>n</mi><mi>f</mi></msub><mi>d</mi><mo>=</mo><mfrac><mi>λ</mi><mn>4</mn></mfrac></mrow></semantics></math>","cap":"只有一次半波损失时薄膜反射相消的条件（左），和单层增透膜的两个条件（右）。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>r</mi><mi>m</mi></msub><mo>=</mo><msqrt><mrow><mi>m</mi><mi>λ</mi><mi>R</mi></mrow></msqrt></mrow></semantics></math>","cap":"牛顿环第 m 个暗环的半径。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi mathvariant=\"normal\">ℓ</mi><mi>c</mi></msub><mo>=</mo><mi>c</mi><mtext> </mtext><msub><mi>τ</mi><mi>c</mi></msub><mo>≈</mo><mfrac><mi>c</mi><mrow><mi mathvariant=\"normal\">Δ</mi><mi>ν</mi></mrow></mfrac><mo>=</mo><mfrac><msup><mi>λ</mi><mn>2</mn></msup><mrow><mi mathvariant=\"normal\">Δ</mi><mi>λ</mi></mrow></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>V</mi><mo>=</mo><mfrac><mrow><msub><mi>I</mi><mi>max</mi><mo>⁡</mo></msub><mo>−</mo><msub><mi>I</mi><mi>min</mi><mo>⁡</mo></msub></mrow><mrow><msub><mi>I</mi><mi>max</mi><mo>⁡</mo></msub><mo>+</mo><msub><mi>I</mi><mi>min</mi><mo>⁡</mo></msub></mrow></mfrac></mrow></semantics></math>","cap":"相干长度、相干时间和条纹可见度。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"normal\">Δ</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msubsup><mo>∫</mo><mn>0</mn><mi mathvariant=\"normal\">∞</mi></msubsup><mi>S</mi><mo stretchy=\"false\">(</mo><mi>σ</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">[</mo><mn>1</mn><mo>+</mo><mi>cos</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mn>2</mn><mi>π</mi><mi>σ</mi><mi mathvariant=\"normal\">Δ</mi><mo stretchy=\"false\">)</mo><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">]</mo><mtext> </mtext><mi mathvariant=\"normal\">d</mi><mi>σ</mi></mrow></semantics></math>","cap":"迈克耳孙干涉图是光谱 S(σ) 的余弦变换（σ 是波数）：傅里叶变换光谱的基础。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>μ</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"normal\">Δ</mi><mi>x</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mfrac><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mo>∫</mo><msub><mi>I</mi><mi>s</mi></msub><mo stretchy=\"false\">(</mo><mi>ξ</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><msup><mi>e</mi><mrow><mo>−</mo><mn>2</mn><mi>π</mi><mi>i</mi><mtext> </mtext><mi>ξ</mi><mi mathvariant=\"normal\">Δ</mi><mi>x</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>λ</mi><mi>z</mi><mo stretchy=\"false\">)</mo></mrow></msup><mtext> </mtext><mi mathvariant=\"normal\">d</mi><mi>ξ</mi></mstyle><mstyle scriptlevel=\"0\" displaystyle=\"true\"><mo>∫</mo><msub><mi>I</mi><mi>s</mi></msub><mo stretchy=\"false\">(</mo><mi>ξ</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><mi mathvariant=\"normal\">d</mi><mi>ξ</mi></mstyle></mfrac></mrow></semantics></math>","cap":"van Cittert–Zernike 定理（一维）：相干度是光源强度分布的傅里叶变换 <span class=\"chm-cites\">[<a href=\"#ref-zernike1938\" data-ref=\"zernike1938\">Zernike 1938</a>]</span>。"}],"example":{"q":"(a) 氦氖激光（633 nm）照亮相距 0.25 mm 的双缝，屏在 1.00 m 外，条纹间距多少？(b) 钠灯的 D 线 588.995 nm 和 589.592 nm，迈克耳孙干涉仪的条纹可见度每隔多少光程差最低一次？镜子要移动多少？(c) 绿色 LED（中心 525 nm，半高宽 35 nm）的相干长度大约多少？","steps":["(a) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>y</mi><mo>=</mo><mi>λ</mi><mi>L</mi><mi mathvariant=\"normal\">/</mi><mi>d</mi><mo>=</mo><mn>633</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>9</mn></mrow></msup><mo>×</mo><mn>1.00</mn><mi mathvariant=\"normal\">/</mi><mn>0.25</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mo>=</mo><mn>2.53</mn></mrow></semantics></math> mm。","(b) 两条线的波数差 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>σ</mi><mo>=</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mn>0.588995</mn><mo>−</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mn>0.589592</mn><mo>=</mo><mn>1.7191</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mtext> </mtext><mi>μ</mi><msup><mtext>m</mtext><mrow><mo>−</mo><mn>1</mn></mrow></msup></mrow></semantics></math>，拍的周期 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi mathvariant=\"normal\">Δ</mi><mi>σ</mi><mo>=</mo><mn>581.7</mn></mrow></semantics></math> μm = 0.582 mm 光程差；镜子每走一半，0.291 mm。","(c) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"normal\">ℓ</mi><mi>c</mi></msub><mo>≈</mo><msup><mi>λ</mi><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mi mathvariant=\"normal\">Δ</mi><mi>λ</mi><mo>=</mo><mn>52</mn><msup><mn>5</mn><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mn>35</mn><mo>=</mo><mn>7875</mn></mrow></semantics></math> nm ≈ 8 μm。"],"a":"钠灯两条线的强度约 2 : 1，所以可见度最低处不是零而是约 1/3；在迈克耳孙演示里选钠灯就能看到。LED 的条纹只在光程差相差几微米之内看得见，这正是 OCT 能分层的原因。"},"cites":"<a href=\"#ref-young1804\" data-ref=\"young1804\">Young 1804</a> · <a href=\"#ref-michelson1887\" data-ref=\"michelson1887\">Michelson &amp; Morley 1887</a> · <a href=\"#ref-zernike1938\" data-ref=\"zernike1938\">Zernike 1938</a> · <a href=\"#ref-hbt1956\" data-ref=\"hbt1956\">Hanbury Brown &amp; Twiss 1956</a> · <a href=\"#ref-jonsson1961\" data-ref=\"jonsson1961\">Jönsson 1961</a> · <a href=\"#ref-hom1987\" data-ref=\"hom1987\">Hong et al. 1987</a> · <a href=\"#ref-tonomura1989\" data-ref=\"tonomura1989\">Tonomura et al. 1989</a> · <a href=\"#ref-huang1991\" data-ref=\"huang1991\">Huang et al. 1991</a> · <a href=\"#ref-arndt1999\" data-ref=\"arndt1999\">Arndt et al. 1999</a> · <a href=\"#ref-ligo2016\" data-ref=\"ligo2016\">LIGO &amp; Virgo 2016</a>"},"diffraction":{"id":"diffraction","body":[{"p":"光遇到障碍物或穿过开口时绕到几何阴影里去，这就是衍射。它不只是“边缘有点模糊”：它给每一台光学仪器定下了分辨率的上限，也是光栅、X 射线晶体学和全息的基础。这一章按开口的形状和观察的距离，把最重要的几种衍射图样过一遍。"},{"h":"夫琅禾费单缝"},{"p":"宽 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi></mrow></semantics></math> 的缝被平行光照亮，在远处（或透镜焦面上）沿角度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ</mi></mrow></semantics></math> 看。把缝分成两半：上半条和下半条的对应点之间光程差是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mi>a</mi><mn>2</mn></mfrac><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow></semantics></math>；当它等于 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mn>2</mn></mrow></semantics></math> 时，两半一一抵消，出现第一条暗纹，即 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>=</mo><mi>λ</mi></mrow></semantics></math>。一般地暗纹在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>=</mo><mi>m</mi><mi>λ</mi></mrow></semantics></math>（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi><mo>=</mo><mo>±</mo><mn>1</mn><mo separator=\"true\">,</mo><mo>±</mo><mn>2</mn><mo separator=\"true\">,</mo><mo>…</mo></mrow></semantics></math>）。完整的强度是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi><mo>=</mo><msub><mi>I</mi><mn>0</mn></msub><mtext> </mtext><msup><mrow><mi mathvariant=\"normal\">s</mi><mi mathvariant=\"normal\">i</mi><mi mathvariant=\"normal\">n</mi><mi mathvariant=\"normal\">c</mi></mrow><mn>2</mn></msup><mi>β</mi></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β</mi><mo>=</mo><mi>π</mi><mi>a</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi></mrow></semantics></math>。中央亮纹的全角宽度约 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>a</mi></mrow></semantics></math>，是旁边亮纹的两倍宽；第一个次极大只有中央的 4.7 %。"},{"p":"这里有一条非常普遍的“不确定关系”：开口越窄，衍射角越大，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>θ</mi><mo>≈</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>a</mi></mrow></semantics></math>。把光挤进一个窄的范围，就要付出方向散开的代价。它和量子力学里的 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>x</mi><mtext> </mtext><mi mathvariant=\"normal\">Δ</mi><mi>p</mi><mo>≳</mo><mi mathvariant=\"normal\">ℏ</mi></mrow></semantics></math> 是同一个傅里叶变换的性质：一个函数和它的傅里叶变换不能同时很窄（第八章）。"},{"h":"菲涅耳衍射和 Cornu 螺线"},{"p":"观察屏不够远时，缝上不同点到屏上一点的距离差里还有一个二次项，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>r</mi><mo>≈</mo><mi>z</mi><mo>+</mo><mo stretchy=\"false\">(</mo><mi>x</mi><mo>−</mo><msup><mi>x</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mn>2</mn><mi>z</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math>。把它放进 Kirchhoff 积分，得到的是菲涅耳积分 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mo stretchy=\"false\">(</mo><mi>u</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msubsup><mo>∫</mo><mn>0</mn><mi>u</mi></msubsup><mi>cos</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>π</mi><msup><mi>t</mi><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mn>2</mn><mo stretchy=\"false\">)</mo><mtext> </mtext><mi mathvariant=\"normal\">d</mi><mi>t</mi></mrow></semantics></math>、<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>S</mi><mo stretchy=\"false\">(</mo><mi>u</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msubsup><mo>∫</mo><mn>0</mn><mi>u</mi></msubsup><mi>sin</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mi>π</mi><msup><mi>t</mi><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mn>2</mn><mo stretchy=\"false\">)</mo><mtext> </mtext><mi mathvariant=\"normal\">d</mi><mi>t</mi></mrow></semantics></math>。在复平面上画出 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>C</mi><mo stretchy=\"false\">(</mo><mi>u</mi><mo stretchy=\"false\">)</mo><mo>+</mo><mi>i</mi><mi>S</mi><mo stretchy=\"false\">(</mo><mi>u</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math>，是一条从两端绕向 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><mo>±</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo separator=\"true\">,</mo><mo>±</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo stretchy=\"false\">)</mo></mrow></semantics></math> 的螺线，叫 Cornu 螺线。屏上一点的振幅，就是螺线上两点之间的弦长；这和第一章的矢量图是同一件事，只是子波的相位按二次方增长，小箭头一圈圈卷了起来。"},{"p":"直边是最干净的例子。在几何阴影的边界上，光强正好是不挡时的 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mn>4</mn></mrow></semantics></math>（螺线从中心到一端的弦长是到另一端的一半）；往亮区走，光强振荡，最大约 1.37，越来越密地趋于 1；往阴影里走，光强单调地衰减到零。演示里选“直边”就能看到这条曲线。缝的两条边各产生这样一组条纹，菲涅耳数 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>F</mi></msub><mo>=</mo><mo stretchy=\"false\">(</mo><mi>a</mi><mi mathvariant=\"normal\">/</mi><mn>2</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>λ</mi><mi>z</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math> 大时它们互不干扰，看到的是几何阴影加边缘条纹；<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>F</mi></msub></mrow></semantics></math> 小于 1 以后两组条纹重叠成夫琅禾费图样。"},{"demo":"fresnel"},{"h":"泊松亮斑：一个想推翻理论的预言"},{"p":"1818 年法国科学院悬赏征文讨论衍射，菲涅耳交了波动理论。评委之一泊松是光的微粒说的支持者，他从菲涅耳的方程推出一个看起来荒谬的结论：一个圆盘的阴影正中央应当有一个亮点，和不挡时一样亮，因为圆盘边缘一圈上所有的点到中心轴的距离相等，子波全部同相。评委 Arago 动手做了实验，亮点真的在那里。菲涅耳获奖，这个点后来被叫作泊松亮斑或 Arago 亮斑。波场水槽的“泊松亮斑”预设是它的二维版本：挡板阴影的中线上有一条亮线。"},{"p":"Babinet 原理把挡板和开口联系起来：一块屏和它的“互补屏”（开口和不透光的部分对调）产生的衍射场相加，等于什么都不挡时的场。所以在不挡时为零的地方（远场里中心以外的所有方向），两者的衍射图样完全一样：一根细丝和一条同样宽的缝，远场衍射图样相同。用激光照一根头发量出它的直径，就是这个原理。"},{"h":"圆孔和艾里斑"},{"p":"透镜、望远镜和瞳孔都是圆的。直径 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>D</mi></mrow></semantics></math> 的圆孔的夫琅禾费图样是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi><mo>=</mo><msub><mi>I</mi><mn>0</mn></msub><mo stretchy=\"false\">[</mo><mn>2</mn><msub><mi>J</mi><mn>1</mn></msub><mo stretchy=\"false\">(</mo><mi>v</mi><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mi>v</mi><msup><mo stretchy=\"false\">]</mo><mn>2</mn></msup></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v</mi><mo>=</mo><mi>π</mi><mi>D</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>J</mi><mn>1</mn></msub></mrow></semantics></math> 是一阶 Bessel 函数。中央亮斑叫艾里斑（Airy 1835 年算出），集中了 83.8 % 的能量，第一个暗环在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>=</mo><mn>1.22</mn><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>D</mi></mrow></semantics></math>。系数 1.22 就是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>J</mi><mn>1</mn></msub></mrow></semantics></math> 的第一个零点 3.8317 除以 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>π</mi></mrow></semantics></math>。"},{"p":"1879 年瑞利在研究光谱仪时提出一个约定：一个点的艾里斑中心落在另一个点的第一暗环上，就算刚好分辨 <span class=\"chm-cites\">[<a href=\"#ref-rayleigh1879\" data-ref=\"rayleigh1879\">Rayleigh 1879</a>]</span>。这时两峰之间的谷是峰高的 73.5 %。于是成像系统的最小可分辨角是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mi>R</mi></msub><mo>=</mo><mn>1.22</mn><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>D</mi></mrow></semantics></math>：口径 3 mm 的瞳孔对 550 nm 约 46 角秒，2.4 m 的哈勃望远镜约 0.058 角秒。这个极限和镜片做得多好无关，它是波动本身的性质。"},{"demo":"airy"},{"p":"显微镜的版本是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mi>min</mi><mo>⁡</mo></msub><mo>≈</mo><mn>0.61</mn><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow></mrow></semantics></math>（自发光的点，比如荧光分子），<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mo>=</mo><mi>n</mi><mi>sin</mi><mo>⁡</mo><mi>α</mi></mrow></semantics></math> 是物镜的数值孔径，油浸物镜最高约 1.4，所以可见光下大约 200 nm。相干照明下的极限由阿贝的理论给出，数字稍有不同（第八章）。突破这个极限的超分辨显微术不是推翻了衍射，而是绕开了“只看一张像”的前提，见第八章。"},{"h":"波带片和“不衍射”的光束"},{"p":"菲涅耳把圆孔分成一圈圈的环带，相邻两带到轴上一点的光程差为 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mn>2</mn></mrow></semantics></math>，第 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow></semantics></math> 带的外半径 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>n</mi></msub><mo>=</mo><msqrt><mrow><mi>n</mi><mi>λ</mi><mi>f</mi></mrow></msqrt></mrow></semantics></math>。相邻两带的贡献相反，互相抵消；把偶数带挡住，剩下的全部同相，轴上那一点就亮得多：这就是菲涅耳波带片，一块用衍射而不是折射聚焦的“透镜”。X 射线几乎不能用玻璃折射，同步辐射和 X 射线显微镜里的聚焦元件正是波带片。"},{"p":"所有有限宽的光束都会衍射散开，但 1987 年 Durnin 等人做出了一种在很长距离上不变宽的光束 <span class=\"chm-cites\">[<a href=\"#ref-durnin1987\" data-ref=\"durnin1987\">Durnin et al. 1987</a>]</span>：它的横截面是零阶 Bessel 函数 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>J</mi><mn>0</mn></msub></mrow></semantics></math>，由一圈锥形汇聚的平面波叠加而成。“不衍射”是有代价的：每一圈旁瓣带着和中心一样多的能量，理想的 Bessel 光束要无限大的功率；实际做出来的只是在有限的一段距离里近似不变。"},{"note":"<b>衍射理论的精确程度。</b> 这一章的公式都来自标量、傍轴或远场的近似。开口和波长差不多大、看的角度很大、或者要关心偏振时，要回到 Maxwell 方程：Sommerfeld 1896 年对理想导电的半平面给出了严格解 <span class=\"chm-cites\">[<a href=\"#ref-sommerfeld1896\" data-ref=\"sommerfeld1896\">Sommerfeld 1896</a>]</span>，今天一般用时域有限差分（FDTD）之类的方法数值求解。","kind":"info"}],"points":[{"h":"单缝暗纹 a sin θ = mλ","p":"中央亮纹全宽 2λ/a，次极大只有 4.7 %。开口越窄，衍射角越大：Δθ ≈ λ/a 和 Δx Δp ≳ ħ 是同一个傅里叶性质。","st":"proved"},{"h":"直边的边界上光强是 1/4","p":"几何阴影边界处的光强精确等于不挡时的四分之一，亮区里最大约 1.37。","st":"proved"},{"h":"泊松亮斑","p":"1818 年泊松想用它驳倒波动说，Arago 的实验证实了它。圆盘阴影中央有一个亮点。","st":"history"},{"h":"瑞利判据 θ = 1.22 λ/D","p":"两峰之间的谷为 73.5 %。这是一个约定，不是物理定律；但 λ/D 这个量级是任何成像都绕不开的。","st":"approx"},{"h":"Babinet 原理","p":"互补的两块屏，远场中心以外的衍射图样完全相同：细丝和同宽的缝一样。","st":"proved"},{"h":"波带片用衍射聚焦","p":"环带半径 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>n</mi></msub><mo>=</mo><msqrt><mrow><mi>n</mi><mi>λ</mi><mi>f</mi></mrow></msqrt></mrow></semantics></math>。X 射线显微镜和同步辐射线站的聚焦元件。","st":"tested"},{"h":"“不衍射”只在有限距离内","p":"Bessel 光束的中心在很长距离上不变宽，但能量分在无数圈旁瓣里；有限孔径的实际光束最终也会散开。","st":"tested"}],"math":[{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo stretchy=\"false\">(</mo><mi>θ</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msub><mi>I</mi><mn>0</mn></msub><mtext> </mtext><msup><mrow><mi mathvariant=\"normal\">s</mi><mi mathvariant=\"normal\">i</mi><mi mathvariant=\"normal\">n</mi><mi mathvariant=\"normal\">c</mi></mrow><mn>2</mn></msup><mi>β</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>β</mi><mo>=</mo><mfrac><mrow><mi>π</mi><mi>a</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow><mi>λ</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>a</mi><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mi>m</mi></msub><mo>=</mo><mi>m</mi><mi>λ</mi></mrow></semantics></math>","cap":"夫琅禾费单缝。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>C</mi><mo stretchy=\"false\">(</mo><mi>u</mi><mo stretchy=\"false\">)</mo><mo>+</mo><mi>i</mi><mi>S</mi><mo stretchy=\"false\">(</mo><mi>u</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msubsup><mo>∫</mo><mn>0</mn><mi>u</mi></msubsup><msup><mi>e</mi><mrow><mi>i</mi><mi>π</mi><msup><mi>t</mi><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mn>2</mn></mrow></msup><mtext> </mtext><mi mathvariant=\"normal\">d</mi><mi>t</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>I</mi><mo stretchy=\"false\">(</mo><mi>x</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mstyle displaystyle=\"false\" scriptlevel=\"0\"><mfrac><mn>1</mn><mn>2</mn></mfrac></mstyle><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">∣</mo><mtext> </mtext><mo stretchy=\"false\">[</mo><mi>C</mi><mo stretchy=\"false\">(</mo><msub><mi>u</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo><mo>−</mo><mi>C</mi><mo stretchy=\"false\">(</mo><msub><mi>u</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mo>+</mo><mi>i</mi><mtext> </mtext><mo stretchy=\"false\">[</mo><mi>S</mi><mo stretchy=\"false\">(</mo><msub><mi>u</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo><mo>−</mo><mi>S</mi><mo stretchy=\"false\">(</mo><msub><mi>u</mi><mn>1</mn></msub><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">]</mo><mtext> </mtext><msup><mo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">∣</mo><mn>2</mn></msup></mrow></semantics></math>","cap":"菲涅耳积分和缝的菲涅耳衍射（以不挡时为 1），u = √(2/(λz))·(缝边 − x)。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo stretchy=\"false\">(</mo><mi>θ</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msub><mi>I</mi><mn>0</mn></msub><msup><mrow><mo fence=\"true\">[</mo><mfrac><mrow><mn>2</mn><msub><mi>J</mi><mn>1</mn></msub><mo stretchy=\"false\">(</mo><mi>v</mi><mo stretchy=\"false\">)</mo></mrow><mi>v</mi></mfrac><mo fence=\"true\">]</mo></mrow><mn>2</mn></msup><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>v</mi><mo>=</mo><mfrac><mrow><mi>π</mi><mi>D</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow><mi>λ</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mn>1</mn></msub><mo>=</mo><mn>1.22</mn><mtext> </mtext><mfrac><mi>λ</mi><mi>D</mi></mfrac></mrow></semantics></math>","cap":"圆孔的艾里图样和第一暗环。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>θ</mi><mi>R</mi></msub><mo>=</mo><mn>1.22</mn><mtext> </mtext><mfrac><mi>λ</mi><mi>D</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>d</mi><mi>min</mi><mo>⁡</mo></msub><mo>≈</mo><mn>0.61</mn><mtext> </mtext><mfrac><mi>λ</mi><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mo>=</mo><mi>n</mi><mi>sin</mi><mo>⁡</mo><mi>α</mi></mrow></semantics></math>","cap":"瑞利判据：望远镜（角度）和显微镜（物面上的距离）<span class=\"chm-cites\">[<a href=\"#ref-rayleigh1879\" data-ref=\"rayleigh1879\">Rayleigh 1879</a>]</span>。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>r</mi><mi>n</mi></msub><mo>=</mo><msqrt><mrow><mi>n</mi><mi>λ</mi><mi>f</mi></mrow></msqrt></mrow></semantics></math>","cap":"菲涅耳波带片第 n 带的外半径（f 是焦距）。"}],"example":{"q":"(a) 一条 0.10 mm 宽的缝，用 633 nm 的激光照，屏在 2.0 m 外。中央亮纹多宽？这时看到的是夫琅禾费图样吗？(b) 瞳孔直径 3 mm、看 550 nm 的光，夜里一辆车的两盏车灯相距 1.4 m，多远以外就分不开了？","steps":["(a) 全宽 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>λ</mi><mi>L</mi><mi mathvariant=\"normal\">/</mi><mi>a</mi><mo>=</mo><mn>2</mn><mo>×</mo><mn>633</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>9</mn></mrow></msup><mo>×</mo><mn>2.0</mn><mi mathvariant=\"normal\">/</mi><mn>1.0</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>4</mn></mrow></msup><mo>=</mo><mn>25</mn></mrow></semantics></math> mm。","<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>N</mi><mi>F</mi></msub><mo>=</mo><mo stretchy=\"false\">(</mo><mi>a</mi><mi mathvariant=\"normal\">/</mi><mn>2</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>λ</mi><mi>L</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mo stretchy=\"false\">(</mo><mn>5</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>5</mn></mrow></msup><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mn>633</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>9</mn></mrow></msup><mo>×</mo><mn>2.0</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>2.0</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mo>≪</mo><mn>1</mn></mrow></semantics></math>：是夫琅禾费。","(b) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mi>R</mi></msub><mo>=</mo><mn>1.22</mn><mo>×</mo><mn>550</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>9</mn></mrow></msup><mi mathvariant=\"normal\">/</mi><mn>3</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup><mo>=</mo><mn>2.24</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>4</mn></mrow></msup></mrow></semantics></math> rad（46″）。","距离 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>1.4</mn><mi mathvariant=\"normal\">/</mi><mn>2.24</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>4</mn></mrow></msup><mo>≈</mo><mn>6.3</mn></mrow></semantics></math> km。"],"a":"这是衍射给的上限。实际上视网膜感光细胞的间距、眼球的像差和大气抖动会让距离更近一些。在艾里斑演示里把口径设成 3 mm，读数里的瑞利极限就是 46 角秒。"},"cites":"<a href=\"#ref-rayleigh1879\" data-ref=\"rayleigh1879\">Rayleigh 1879</a> · <a href=\"#ref-sommerfeld1896\" data-ref=\"sommerfeld1896\">Sommerfeld 1896</a> · <a href=\"#ref-durnin1987\" data-ref=\"durnin1987\">Durnin et al. 1987</a>"},"gratings":{"id":"gratings","body":[{"p":"双缝的条纹又宽又柔和，亮纹和暗纹各占一半。缝变多以后，图样发生质变：亮纹越来越细、越来越亮，中间几乎全暗。这是因为 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow></semantics></math> 支等长的小箭头只有在每支都同向（相邻缝的光程差正好是整数个波长）时才排成一条长 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow></semantics></math> 倍的直线，强度是单缝的 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>N</mi><mn>2</mn></msup></mrow></semantics></math> 倍；稍微偏一点，箭头就绕成一个闭合的多边形。光栅就是把这件事做到极致：几万条缝，亮纹窄到能把两条相差千分之一的波长分开。"},{"h":"N 条缝"},{"p":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow></semantics></math> 条宽 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi></mrow></semantics></math>、间距 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow></semantics></math> 的缝，远场强度是单缝因子乘多缝因子：<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi><mo>=</mo><msub><mi>I</mi><mn>0</mn></msub><mtext> </mtext><msup><mrow><mi mathvariant=\"normal\">s</mi><mi mathvariant=\"normal\">i</mi><mi mathvariant=\"normal\">n</mi><mi mathvariant=\"normal\">c</mi></mrow><mn>2</mn></msup><mi>β</mi><mtext> </mtext><mo stretchy=\"false\">[</mo><mi>sin</mi><mo>⁡</mo><mi>N</mi><mi>γ</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>N</mi><mi>sin</mi><mo>⁡</mo><mi>γ</mi><mo stretchy=\"false\">)</mo><msup><mo stretchy=\"false\">]</mo><mn>2</mn></msup></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>γ</mi><mo>=</mo><mi>π</mi><mi>d</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi></mrow></semantics></math>。多缝因子在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>=</mo><mi>m</mi><mi>λ</mi></mrow></semantics></math> 处等于 1，是主极大；两个主极大之间有 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi><mo>−</mo><mn>1</mn></mrow></semantics></math> 个零点和 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi><mo>−</mo><mn>2</mn></mrow></semantics></math> 个次极大，最强的次极大随 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow></semantics></math> 增大而趋于主极大的约 4.7 %。主极大的半宽约 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>N</mi><mi>d</mi><mi>cos</mi><mo>⁡</mo><mi>θ</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math>：缝越多越细。单缝因子只管各级的相对亮度，缺级就是它的零点碰上了主极大。"},{"h":"光栅方程和分辨本领"},{"p":"光以入射角 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mi>i</mi></msub></mrow></semantics></math> 射到周期为 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow></semantics></math> 的光栅上，第 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow></semantics></math> 级衍射光的方向满足 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo stretchy=\"false\">(</mo><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mi>m</mi></msub><mo>−</mo><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mi>i</mi></msub><mo stretchy=\"false\">)</mo><mo>=</mo><mi>m</mi><mi>λ</mi></mrow></semantics></math>。<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi><mo>=</mo><mn>0</mn></mrow></semantics></math> 是不分光的直射（或镜面反射），其余各级里不同波长偏转不同的角度，角色散 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">d</mi><mi>θ</mi><mi mathvariant=\"normal\">/</mi><mi mathvariant=\"normal\">d</mi><mi>λ</mi><mo>=</mo><mi>m</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>d</mi><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>m</mi></msub><mo stretchy=\"false\">)</mo></mrow></semantics></math>。刻线越密、级次越高，颜色分得越开。"},{"p":"色散大不等于分得开：两条谱线还要比各自的宽度分得更开才行。按瑞利判据（一条线的极大落在另一条的第一个零点上），能分辨的最小波长差是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>λ</mi><mo>=</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>m</mi><mi>N</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math>，即分辨本领 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi mathvariant=\"normal\">Δ</mi><mi>λ</mi><mo>=</mo><mi>m</mi><mi>N</mi></mrow></semantics></math> <span class=\"chm-cites\">[<a href=\"#ref-rayleigh1879\" data-ref=\"rayleigh1879\">Rayleigh 1879</a>]</span>。它只和级次与被照亮的总缝数有关，和缝距无关。钠的两条 D 线相差 0.597 nm，在第一级要 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi><mo>≥</mo><mn>589.3</mn><mi mathvariant=\"normal\">/</mi><mn>0.597</mn><mo>≈</mo><mn>990</mn></mrow></semantics></math> 条缝，演示里可以看到 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow></semantics></math> 从 500 调到 2000 时它们怎样从一团分成两条。"},{"demo":"grating"},{"p":"高级次分辨本领高，但有一个麻烦：第 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi></mrow></semantics></math> 级的 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi></mrow></semantics></math> 和第 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi><mo>+</mo><mn>1</mn></mrow></semantics></math> 级的 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi>m</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>m</mi><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo></mrow></semantics></math> 落在同一个角度上，互相重叠。不重叠的波长范围叫自由光谱范围，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><msub><mi>λ</mi><mrow><mi mathvariant=\"normal\">F</mi><mi mathvariant=\"normal\">S</mi><mi mathvariant=\"normal\">R</mi></mrow></msub><mo>=</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>m</mi></mrow></semantics></math>。所以普通光谱仪用第一级，前面放一块滤光片挡掉二级光（否则 400 nm 的二级光会混进 800 nm 的一级光里）；中阶梯光栅（echelle）用几十到上百级，再用一块棱镜在垂直方向把各级分开，排成一张二维的谱图。"},{"h":"闪耀：把光赶到想要的那一级"},{"p":"简单的透射光栅把大部分能量浪费在零级（不分光）里。反射光栅可以把每条刻槽做成一个小斜面，斜面的镜面反射方向恰好对准某一级（比如 m = 1）的衍射方向，于是这一级在设计波长附近能拿到 70–90 % 的光。这叫闪耀光栅，斜面的倾角叫闪耀角。演示里调“缝宽 / 周期”是另一个道理的同一件事：单缝包络决定能量分给哪几级。"},{"h":"历史：从细金属丝到刻线机"},{"p":"1814 年 Fraunhofer 在太阳光谱里看到并标出了几百条暗线，后来知道是太阳和地球大气里原子的吸收线（钠的 D 线就是他命名的“D”）。1821 年他用细金属丝绕成栅，第一次用光栅量出了谱线的绝对波长。真正改变光谱学的是十九世纪末的刻线机：Rowland 在约翰斯·霍普金斯大学造的机器用一根精密螺杆，在镜面金属上刻出每英寸一万四千多条刻线，并且发明了凹面光栅，刻在球面上，自己就能成像，不再需要透镜 <span class=\"chm-cites\">[<a href=\"#ref-rowland1882\" data-ref=\"rowland1882\">Rowland 1882</a>]</span>。之后几十年的原子光谱数据，大多来自这类光栅。"},{"p":"今天的光栅大多是全息光栅（用两束激光干涉出的条纹曝光光刻胶）或者从母版复制的。光纤里写进的周期性折射率变化叫光纤布拉格光栅，只反射一个很窄的波段，用作通信里的滤波器和测应变、测温度的传感器；它的原理和第五章晶体里的布拉格反射一样。"},{"h":"棱镜和光栅"},{"p":"棱镜靠色散（折射率随波长变化）分光，分辨本领 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mi>b</mi><mtext> </mtext><mi mathvariant=\"normal\">d</mi><mi>n</mi><mi mathvariant=\"normal\">/</mi><mi mathvariant=\"normal\">d</mi><mi>λ</mi></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b</mi></mrow></semantics></math> 是棱镜底边的长度。一块 5 cm 的火石玻璃棱镜在可见光里 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi></mrow></semantics></math> 约几千；一块 5 cm、每毫米 600 线的光栅在第一级 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mn>30</mn><mtext> </mtext><mn>000</mn></mrow></semantics></math>。棱镜的优点是只有一个“级”、没有重叠，透过率高；缺点是色散不均匀（蓝端远比红端分得开），在紫外和红外还要换材料。"},{"h":"光栅的其他用处"},{"p":"两块平行的光栅能让不同颜色走不同长的路，于是可以把一个超短脉冲拉长或者压缩。1985 年 Strickland 和 Mourou 先把脉冲拉长、降低峰值功率再放大，最后用光栅对把它压回去 <span class=\"chm-cites\">[<a href=\"#ref-strickland1985\" data-ref=\"strickland1985\">Strickland &amp; Mourou 1985</a>]</span>，这就是啁啾脉冲放大（CPA）。它让桌面上的激光达到太瓦以上的峰值功率，今天的眼科手术和阿秒科学都靠它。"},{"p":"自然界和日常生活里的“光栅”到处都是：光盘的数据轨道间距 1.6 μm（CD）或 0.74 μm（DVD），斜着看有彩虹；大闪蝶翅膀鳞片上周期为几百纳米的脊让它显出不依赖色素的蓝色（结构色）。化学实验室里的紫外–可见、荧光、拉曼和原子发射光谱仪，核心都是一块光栅加一个阵列探测器，见<a href=\"../spectra/#m-uvvis\">谱图馆 · 紫外–可见</a>和<a href=\"../spectra/#m-raman\">拉曼</a>。"}],"points":[{"h":"主极大强度 ∝ N²，宽度 ∝ 1/N","p":"两个主极大之间有 N − 1 个零点、N − 2 个次极大；能量守恒，所以亮纹越亮就越窄。","st":"proved"},{"h":"光栅方程 d(sin θ_m − sin θ_i) = mλ","p":"只由周期决定方向；缝的形状只影响各级的亮度。","st":"proved"},{"h":"分辨本领 R = mN","p":"和缝距无关，只和级次与被照亮的缝数有关。分开钠双线在第一级要约 990 条缝。","st":"proved"},{"h":"自由光谱范围 λ/m","p":"级次越高，各级之间越容易重叠；中阶梯光栅用棱镜在另一个方向把各级分开。","st":"proved"},{"h":"闪耀把能量集中到一级","p":"刻槽做成斜面，镜面反射方向对准设计的衍射级，效率可到 70–90 %。","st":"tested"},{"h":"Rowland 的凹面光栅","p":"刻在球面上的光栅自己成像，不再需要透镜；十九世纪末原子光谱的主力。","st":"history"},{"h":"啁啾脉冲放大","p":"用光栅对拉长、再压缩超短脉冲，峰值功率提高几个数量级（2018 年诺贝尔物理学奖）。","st":"tested"}],"math":[{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo stretchy=\"false\">(</mo><mi>θ</mi><mo stretchy=\"false\">)</mo><mo>=</mo><msub><mi>I</mi><mn>0</mn></msub><mtext> </mtext><msup><mrow><mi mathvariant=\"normal\">s</mi><mi mathvariant=\"normal\">i</mi><mi mathvariant=\"normal\">n</mi><mi mathvariant=\"normal\">c</mi></mrow><mn>2</mn></msup><mi>β</mi><msup><mrow><mo fence=\"true\">[</mo><mfrac><mrow><mi>sin</mi><mo>⁡</mo><mi>N</mi><mi>γ</mi></mrow><mrow><mi>N</mi><mi>sin</mi><mo>⁡</mo><mi>γ</mi></mrow></mfrac><mo fence=\"true\">]</mo></mrow><mn>2</mn></msup><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>β</mi><mo>=</mo><mfrac><mrow><mi>π</mi><mi>a</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow><mi>λ</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"1em\"/><mi>γ</mi><mo>=</mo><mfrac><mrow><mi>π</mi><mi>d</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow><mi>λ</mi></mfrac></mrow></semantics></math>","cap":"N 条缝的夫琅禾费图样（中央归一为 1）。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>d</mi><mtext> </mtext><mo stretchy=\"false\">(</mo><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mi>m</mi></msub><mo>−</mo><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mi>i</mi></msub><mo stretchy=\"false\">)</mo><mo>=</mo><mi>m</mi><mi>λ</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mfrac><mrow><mi mathvariant=\"normal\">d</mi><msub><mi>θ</mi><mi>m</mi></msub></mrow><mrow><mi mathvariant=\"normal\">d</mi><mi>λ</mi></mrow></mfrac><mo>=</mo><mfrac><mi>m</mi><mrow><mi>d</mi><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>m</mi></msub></mrow></mfrac></mrow></semantics></math>","cap":"光栅方程和角色散。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>R</mi><mo>=</mo><mfrac><mi>λ</mi><mrow><mi mathvariant=\"normal\">Δ</mi><msub><mi>λ</mi><mi>min</mi><mo>⁡</mo></msub></mrow></mfrac><mo>=</mo><mi>m</mi><mi>N</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi mathvariant=\"normal\">Δ</mi><msub><mi>λ</mi><mrow><mi mathvariant=\"normal\">F</mi><mi mathvariant=\"normal\">S</mi><mi mathvariant=\"normal\">R</mi></mrow></msub><mo>=</mo><mfrac><mi>λ</mi><mi>m</mi></mfrac></mrow></semantics></math>","cap":"分辨本领和自由光谱范围 <span class=\"chm-cites\">[<a href=\"#ref-rayleigh1879\" data-ref=\"rayleigh1879\">Rayleigh 1879</a>]</span>。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>R</mi><mtext>prism</mtext></msub><mo>=</mo><mi>b</mi><mtext> </mtext><mfrac><mrow><mi mathvariant=\"normal\">d</mi><mi>n</mi></mrow><mrow><mi mathvariant=\"normal\">d</mi><mi>λ</mi></mrow></mfrac></mrow></semantics></math>","cap":"棱镜的分辨本领（b 是底边长）。"}],"example":{"q":"一块每毫米 600 线的光栅，被照亮的宽度 5.0 cm，光正入射。(a) 钠 589.3 nm 的一级衍射角是多少？最多能看到几级？(b) 一级的分辨本领和能分开的最小波长差？(c) 一级的自由光谱范围从 400 nm 开始到哪里为止？","steps":["(a) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi><mo>=</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mn>600</mn></mrow></semantics></math> mm <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>1.667</mn></mrow></semantics></math> μm。<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mn>1</mn></msub><mo>=</mo><mn>0.5893</mn><mi mathvariant=\"normal\">/</mi><mn>1.667</mn><mo>=</mo><mn>0.354</mn></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mn>1</mn></msub><mo>=</mo><mn>20.7</mn><mi mathvariant=\"normal\">°</mi></mrow></semantics></math>。<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m</mi><mo>≤</mo><mi>d</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi><mo>=</mo><mn>2.83</mn></mrow></semantics></math>，所以每边最多 2 级。","(b) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi><mo>=</mo><mn>600</mn><mo>×</mo><mn>50</mn><mo>=</mo><mn>30</mn><mtext> </mtext><mn>000</mn></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mi>m</mi><mi>N</mi><mo>=</mo><mn>30</mn><mtext> </mtext><mn>000</mn></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ</mi><mi>λ</mi><mo>=</mo><mn>589.3</mn><mi mathvariant=\"normal\">/</mi><mn>30</mn><mtext> </mtext><mn>000</mn><mo>=</mo><mn>0.020</mn></mrow></semantics></math> nm。","(c) 400 nm 的二级光和 800 nm 的一级光重合，所以一级不重叠的范围是 400 到 800 nm。"],"a":"这块光栅分开钠双线绰绰有余（需要的 R 只有约 1000）；实际谱仪的分辨率常常被狭缝宽度和探测器像素限制，达不到 mN。"},"cites":"<a href=\"#ref-rayleigh1879\" data-ref=\"rayleigh1879\">Rayleigh 1879</a> · <a href=\"#ref-rowland1882\" data-ref=\"rowland1882\">Rowland 1882</a> · <a href=\"#ref-strickland1985\" data-ref=\"strickland1985\">Strickland &amp; Mourou 1985</a>"},"xray":{"id":"xray","body":[{"p":"可见光光栅的周期是微米，正好和可见光的波长相当。要用衍射看原子，需要一个周期为零点几纳米的光栅和同样短的波长。大自然现成准备好了前者：晶体里原子排得整整齐齐，间距约 0.1 到 1 nm。后者是 X 射线：铜靶发出的 Kα 线波长 1.5406 Å（0.154 nm）。这一章是第四章的三维版本。"},{"h":"1912：X 射线是波，晶体是格子"},{"p":"1912 年，人们还不知道 X 射线是波还是粒子，也不知道晶体里的原子是不是真的排成格子。Laue 想到，如果两件事都成立，晶体就该像一块三维光栅一样衍射 X 射线。Friedrich 和 Knipping 把一块硫酸铜晶体放进 X 射线束里，照相底片上果然出现了规则排列的斑点 <span class=\"chm-cites\">[<a href=\"#ref-laue1913\" data-ref=\"laue1913\">Friedrich, Knipping &amp; Laue 1913</a>]</span>。一张照片同时证明了两件事。"},{"p":"Laue 用三个方向上的光栅方程来解释这些斑点，三个条件要同时满足，相当复杂。几个月后，年轻的 W. L. Bragg 给出了一个简单得多的图像：把晶体看成一叠间距为 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d</mi></mrow></semantics></math> 的平行原子面，每层像一面极薄的半透镜，反射一点点 X 射线；相邻两层反射的光程差是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>d</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow></semantics></math>（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ</mi></mrow></semantics></math> 是相对晶面的掠射角），只有它等于整数个波长时各层的反射才同相叠加 <span class=\"chm-cites\">[<a href=\"#ref-bragg1913\" data-ref=\"bragg1913\">Bragg &amp; Bragg 1913</a>]</span>："},{"math":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>n</mi><mi>λ</mi><mo>=</mo><mn>2</mn><mi>d</mi><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow></semantics></math>","cap":"Bragg 定律。注意 θ 是和晶面的夹角，衍射线和入射线之间的夹角是 2θ。"},{"p":"Bragg 父子随即用自己造的 X 射线分光计测出了 NaCl、KCl 和金刚石的结构，这是人类第一次知道原子在固体里具体怎样排。氯化钠里根本没有“NaCl 分子”，每个 Na⁺ 被六个 Cl⁻ 包围，这个结论当年让一些化学家很不舒服。下面的演示把布拉格反射拆成一层一层的小箭头：对准布拉格角时箭头排成直线，偏一点就卷成圈。"},{"demo":"bragg"},{"h":"倒易格子和 Ewald 球"},{"p":"更一般的说法是 Laue 条件：入射波矢 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold\">k</mi></mrow></semantics></math> 和出射波矢 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi mathvariant=\"bold\">k</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup></mrow></semantics></math>（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">∣</mi><mi mathvariant=\"bold\">k</mi><mi mathvariant=\"normal\">∣</mi><mo>=</mo><mi mathvariant=\"normal\">∣</mi><msup><mi mathvariant=\"bold\">k</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup><mi mathvariant=\"normal\">∣</mi><mo>=</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>λ</mi></mrow></semantics></math>，晶体学的习惯不带 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>π</mi></mrow></semantics></math>）之差，必须等于倒易格子的一个矢量 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi mathvariant=\"bold\">G</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub></mrow></semantics></math>。倒易格子由 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi mathvariant=\"bold\">a</mi><mo>∗</mo></msup><mo>=</mo><mo stretchy=\"false\">(</mo><mi mathvariant=\"bold\">b</mi><mo>×</mo><mi mathvariant=\"bold\">c</mi><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mi>V</mi></mrow></semantics></math> 等三个基矢张成，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">∣</mi><msub><mi mathvariant=\"bold\">G</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mi mathvariant=\"normal\">∣</mi><mo>=</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><msub><mi>d</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub></mrow></semantics></math>，方向垂直于 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><mi>h</mi><mi>k</mi><mi>l</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math> 晶面。Laue 条件和 Bragg 定律是同一件事：取模就得到 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi><mo>=</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>d</mi></mrow></semantics></math>。"},{"p":"Ewald 给了它一个几何图像：以 1/λ 为半径画一个球，入射波矢的终点放在倒易格子的原点上。哪个倒易格点恰好落在球面上，哪个方向就有衍射。单色光照一块不动的单晶，球面上一般碰不到几个格点，所以要转动晶体（转晶法、四圆衍射仪），或者用连续谱的 X 射线让球有一个厚度（Laue 法），或者用无数取向各异的小晶粒（粉末法）。"},{"h":"结构因子：峰的强度里藏着原子的位置"},{"p":"晶胞的大小和形状只决定衍射的方向；晶胞里原子怎样摆，决定每个方向上有多强。<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><mi>h</mi><mi>k</mi><mi>l</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math> 衍射的振幅是结构因子 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mo>=</mo><msub><mo>∑</mo><mi>j</mi></msub><msub><mi>f</mi><mi>j</mi></msub><mtext> </mtext><msup><mi>e</mi><mrow><mn>2</mn><mi>π</mi><mi>i</mi><mo stretchy=\"false\">(</mo><mi>h</mi><msub><mi>x</mi><mi>j</mi></msub><mo>+</mo><mi>k</mi><msub><mi>y</mi><mi>j</mi></msub><mo>+</mo><mi>l</mi><msub><mi>z</mi><mi>j</mi></msub><mo stretchy=\"false\">)</mo></mrow></msup></mrow></semantics></math>，求和遍及晶胞里的原子，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f</mi><mi>j</mi></msub></mrow></semantics></math> 是原子散射因子（大约正比于电子数，随 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi></mrow></semantics></math> 增大而下降），<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>j</mi></msub><mo separator=\"true\">,</mo><msub><mi>y</mi><mi>j</mi></msub><mo separator=\"true\">,</mo><msub><mi>z</mi><mi>j</mi></msub><mo stretchy=\"false\">)</mo></mrow></semantics></math> 是分数坐标。强度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi><mo>∝</mo><mi mathvariant=\"normal\">∣</mi><mi>F</mi><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup></mrow></semantics></math>。"},{"p":"有对称性时某些 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi></mrow></semantics></math> 恒为零，叫系统消光，它们是判断晶格类型的指纹。体心格子（原子在 0,0,0 和 ½,½,½）要求 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h</mi><mo>+</mo><mi>k</mi><mo>+</mo><mi>l</mi></mrow></semantics></math> 为偶数；面心格子要求 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h</mi><mo separator=\"true\">,</mo><mi>k</mi><mo separator=\"true\">,</mo><mi>l</mi></mrow></semantics></math> 全奇或全偶；金刚石结构在面心的基础上再去掉 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h</mi><mo>+</mo><mi>k</mi><mo>+</mo><mi>l</mi><mo>=</mo><mn>4</mn><mi>n</mi><mo>+</mo><mn>2</mn></mrow></semantics></math> 的那些，所以硅的 (200) 不出现。岩盐结构里全奇的峰正比于 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><msub><mi>f</mi><mo>+</mo></msub><mo>−</mo><msub><mi>f</mi><mo>−</mo></msub><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></semantics></math>：NaCl 的 (111) 很弱，KCl 里 K⁺ 和 Cl⁻ 都有 18 个电子，(111) 几乎完全消失，图样看起来像一个边长减半的简单立方。Bragg 父子当年正是从这里认出了两者是同一种结构。"},{"h":"粉末衍射"},{"p":"把晶体磨成粉，每族晶面都有一些晶粒恰好处在布拉格角上，衍射线组成一个个圆锥（Debye–Scherrer 环）。让探测器扫过 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>θ</mi></mrow></semantics></math>，就得到一张峰图：峰位给出晶胞，峰强给出原子位置，峰宽给出晶粒大小和应变。每种晶相的峰图都不一样，像指纹一样，所以粉末衍射是鉴定固体物相的首选，数据库里收了几十万张标准谱。"},{"p":"晶粒很小时，参与衍射的晶面层数有限，峰就变宽（上面第一个演示里把层数 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow></semantics></math> 调小时看到的效应）。Scherrer 公式 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β</mi><mo>=</mo><mi>K</mi><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>L</mi><mi>cos</mi><mo>⁡</mo><mi>θ</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math> 把峰的宽度（弧度）和晶粒的尺寸 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>L</mi></mrow></semantics></math> 联系起来，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>K</mi><mo>≈</mo><mn>0.9</mn></mrow></semantics></math>；Patterson 1939 年仔细讨论过这个公式在什么意义上成立 <span class=\"chm-cites\">[<a href=\"#ref-patterson1939\" data-ref=\"patterson1939\">Patterson 1939</a>]</span>。1969 年 Rietveld 提出不再一个个地分峰，而是用晶体结构模型直接拟合整张衍射图 <span class=\"chm-cites\">[<a href=\"#ref-rietveld1969\" data-ref=\"rietveld1969\">Rietveld 1969</a>]</span>，这就是今天粉末结构精修的标准方法。"},{"demo":"powder"},{"h":"相位问题"},{"p":"如果知道每个 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub></mrow></semantics></math>（模和相位），做一次傅里叶逆变换就得到晶胞里的电子密度，原子就在电子密度的峰上。麻烦在于探测器只记录强度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">∣</mi><mi>F</mi><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup></mrow></semantics></math>，相位全丢了。这叫相位问题，它让晶体结构测定在几十年里都是一门手艺。1934 年 Patterson 发现，不要相位、直接拿 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">∣</mi><mi>F</mi><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup></mrow></semantics></math> 做傅里叶变换，得到的是电子密度的自相关函数，峰的位置是原子之间的距离矢量 <span class=\"chm-cites\">[<a href=\"#ref-patterson1934\" data-ref=\"patterson1934\">Patterson 1934</a>]</span>；重原子的距离矢量最显眼，可以先把它们定下来。后来的“直接法”用统计关系从强度里推出相位（1985 年诺贝尔化学奖），小分子结构从此几乎可以自动解出。蛋白质则常用重原子置换或反常散射来定相位。"},{"h":"DNA、蛋白质和准晶"},{"p":"衍射不一定要完美的三维晶体。1953 年 Franklin 和 Gosling 拍下 B 型 DNA 纤维的衍射图，一个醒目的“X”形图案：螺旋的衍射图样就是一个十字，从层线的间距读出螺距 3.4 nm，从子午线上的强斑读出碱基对间距 0.34 nm <span class=\"chm-cites\">[<a href=\"#ref-franklin1953\" data-ref=\"franklin1953\">Franklin &amp; Gosling 1953</a>]</span>。这和 Watson、Crick 的模型发表在同一期《自然》上。1958 年 Kendrew 等人用 X 射线衍射给出了第一个蛋白质（肌红蛋白）的三维结构 <span class=\"chm-cites\">[<a href=\"#ref-kendrew1958\" data-ref=\"kendrew1958\">Kendrew et al. 1958</a>]</span>，今天蛋白质数据库里的二十多万个结构，大部分来自 X 射线晶体学。"},{"p":"1982 年 Shechtman 用电子衍射看到一种铝锰合金的衍射图有尖锐的斑点，却呈现十次对称 <span class=\"chm-cites\">[<a href=\"#ref-shechtman1984\" data-ref=\"shechtman1984\">Shechtman et al. 1984</a>]</span>。尖锐的斑点意味着长程有序，可是五次和十次对称不能和平移周期共存：这是一种有序但不周期的固体，准晶。国际晶体学联合会后来把“晶体”重新定义为“衍射图基本上是分立的固体”，2011 年 Shechtman 获诺贝尔化学奖。"},{"h":"没有晶体的衍射：X 射线激光"},{"p":"单个分子的衍射太弱，要放大信号才得把无数分子排成晶体。2000 年 Neutze 等人的模拟提出了另一条路：用极强、只有几飞秒长的 X 射线脉冲，在分子被打碎之前就把衍射图记下来（“先衍射、后毁坏”）<span class=\"chm-cites\">[<a href=\"#ref-neutze2000\" data-ref=\"neutze2000\">Neutze et al. 2000</a>]</span>。X 射线自由电子激光建成后，2011 年 Chapman 等人用它从几十万颗纳米晶体里一颗一颗地收集衍射图，拼出了光系统 I 的结构 <span class=\"chm-cites\">[<a href=\"#ref-chapman2011\" data-ref=\"chapman2011\">Chapman et al. 2011</a>]</span>。另一方面，1999 年 Miao 等人证明，只要衍射图采样得比布拉格条件更密（过采样），非晶的样品也能用迭代算法找回相位、重建像 <span class=\"chm-cites\">[<a href=\"#ref-miao1999\" data-ref=\"miao1999\">Miao et al. 1999</a>]</span>，这叫相干衍射成像，第八章再谈。"},{"p":"电子和中子也能衍射。电子和物质相互作用强，适合薄样品和表面（以及冷冻电镜）；中子对轻原子（氢）和磁矩敏感。三者用的是同一套 Bragg 和结构因子的语言。化学学科馆的<a href=\"../chemistry/structural/#c-diffraction\">结构化学 · 衍射与结构解析</a>一章讲直接法、精修和 R 因子；谱图馆有<a href=\"../spectra/#m-pxrd\">粉末衍射</a>和<a href=\"../spectra/#m-scxrd\">单晶衍射</a>的读谱方法。"}],"points":[{"h":"1912 年一张照片证明了两件事","p":"X 射线是波，晶体里的原子排成格子。Laue 1914 年、Bragg 父子 1915 年分别获诺贝尔物理学奖。","st":"history"},{"h":"Bragg 定律 nλ = 2d sin θ","p":"和 Laue 条件 k′ − k = G 等价；Ewald 球把它画成几何。","st":"proved"},{"h":"位置给晶胞，强度给原子","p":"结构因子 F_hkl 是晶胞里原子散射的相干和；系统消光是格子类型的指纹。","st":"proved"},{"h":"Scherrer：峰宽 ∝ 1/晶粒大小","p":"β = Kλ/(L cos θ)，K ≈ 0.9。只适合约 100 nm 以下的晶粒，应变和仪器展宽也会让峰变宽。","st":"approx"},{"h":"相位问题","p":"探测器只记 |F|²；Patterson 函数、直接法、重原子和反常散射是绕过它的几种办法。","st":"proved"},{"h":"准晶：有序但不周期","p":"尖锐的衍射斑和十次对称同时出现；“晶体”的定义因此改成了“衍射图基本分立”。","st":"tested"},{"h":"先衍射、后毁坏","p":"飞秒 X 射线脉冲赶在样品被打碎之前记下衍射图；单个分子的结构测定仍在发展中。","st":"frontier"}],"math":[{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msup><mi mathvariant=\"bold\">k</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup><mo>−</mo><mi mathvariant=\"bold\">k</mi><mo>=</mo><msub><mi mathvariant=\"bold\">G</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mo>=</mo><mi>h</mi><msup><mi mathvariant=\"bold\">a</mi><mo>∗</mo></msup><mo>+</mo><mi>k</mi><msup><mi mathvariant=\"bold\">b</mi><mo>∗</mo></msup><mo>+</mo><mi>l</mi><msup><mi mathvariant=\"bold\">c</mi><mo>∗</mo></msup><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi mathvariant=\"normal\">∣</mi><msub><mi mathvariant=\"bold\">G</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mi mathvariant=\"normal\">∣</mi><mo>=</mo><mfrac><mn>1</mn><msub><mi>d</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub></mfrac></mrow></semantics></math>","cap":"Laue 条件和倒易格子（晶体学的约定，|k| = 1/λ）。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>d</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mo>=</mo><mfrac><mi>a</mi><msqrt><mrow><msup><mi>h</mi><mn>2</mn></msup><mo>+</mo><msup><mi>k</mi><mn>2</mn></msup><mo>+</mo><msup><mi>l</mi><mn>2</mn></msup></mrow></msqrt></mfrac><mspace width=\"1em\"/><mtext>(cubic)</mtext></mrow></semantics></math>","cap":"立方晶系的晶面间距。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>F</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mo>=</mo><munder><mo>∑</mo><mi>j</mi></munder><msub><mi>f</mi><mi>j</mi></msub><mtext> ⁣</mtext><mrow><mo fence=\"true\">(</mo><mstyle displaystyle=\"false\" scriptlevel=\"0\"><mfrac><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi></mrow><mi>λ</mi></mfrac></mstyle><mo fence=\"true\">)</mo></mrow><msup><mi>e</mi><mrow><mo>−</mo><msub><mi>B</mi><mi>j</mi></msub><mo stretchy=\"false\">(</mo><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mi mathvariant=\"normal\">/</mi><mi>λ</mi><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup></mrow></msup><mtext> </mtext><msup><mi>e</mi><mrow><mn>2</mn><mi>π</mi><mi>i</mi><mo stretchy=\"false\">(</mo><mi>h</mi><msub><mi>x</mi><mi>j</mi></msub><mo>+</mo><mi>k</mi><msub><mi>y</mi><mi>j</mi></msub><mo>+</mo><mi>l</mi><msub><mi>z</mi><mi>j</mi></msub><mo stretchy=\"false\">)</mo></mrow></msup><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>I</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mo>∝</mo><msub><mi>m</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mtext> </mtext><mi mathvariant=\"normal\">∣</mi><msub><mi>F</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup><mtext> </mtext><mfrac><mrow><mn>1</mn><mo>+</mo><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mn>2</mn><mi>θ</mi></mrow><mrow><msup><mrow><mi>sin</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mi>θ</mi><mi>cos</mi><mo>⁡</mo><mi>θ</mi></mrow></mfrac></mrow></semantics></math>","cap":"结构因子（含 Debye–Waller 因子）和粉末衍射的强度：多重度 × |F|² × 洛伦兹–偏振因子。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>β</mi><mo>=</mo><mfrac><mrow><mi>K</mi><mi>λ</mi></mrow><mrow><mi>L</mi><mi>cos</mi><mo>⁡</mo><mi>θ</mi></mrow></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>K</mi><mo>≈</mo><mn>0.9</mn></mrow></semantics></math>","cap":"Scherrer 公式：β 是峰的半高全宽（2θ，弧度）<span class=\"chm-cites\">[<a href=\"#ref-patterson1939\" data-ref=\"patterson1939\">Patterson 1939</a>]</span>。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>ρ</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"bold\">r</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mfrac><mn>1</mn><mi>V</mi></mfrac><munder><mo>∑</mo><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></munder><msub><mi>F</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mtext> </mtext><msup><mi>e</mi><mrow><mo>−</mo><mn>2</mn><mi>π</mi><mi>i</mi><mtext> </mtext><msub><mi mathvariant=\"bold\">G</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mo>⋅</mo><mi mathvariant=\"bold\">r</mi></mrow></msup><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>P</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"bold\">u</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mfrac><mn>1</mn><mi>V</mi></mfrac><munder><mo>∑</mo><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></munder><mi mathvariant=\"normal\">∣</mi><msub><mi>F</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup><mi>cos</mi><mo>⁡</mo><mo stretchy=\"false\">(</mo><mn>2</mn><mi>π</mi><mtext> </mtext><msub><mi mathvariant=\"bold\">G</mi><mrow><mi>h</mi><mi>k</mi><mi>l</mi></mrow></msub><mo>⋅</mo><mi mathvariant=\"bold\">u</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math>","cap":"电子密度是结构因子的傅里叶级数；Patterson 函数只用强度，峰在原子间的距离矢量上 <span class=\"chm-cites\">[<a href=\"#ref-patterson1934\" data-ref=\"patterson1934\">Patterson 1934</a>]</span>。"}],"example":{"q":"NaCl 的晶胞参数 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a</mi><mo>=</mo><mn>5.640</mn></mrow></semantics></math> Å，用铜靶 Kα₁（1.5406 Å）。(a) (200) 峰在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>θ</mi></mrow></semantics></math> 多少度？(b) 为什么没有 (100) 峰？(c) 如果晶粒只有 20 nm，(200) 峰的 Scherrer 宽度是多少？","steps":["(a) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>d</mi><mn>200</mn></msub><mo>=</mo><mn>5.640</mn><mi mathvariant=\"normal\">/</mi><mn>2</mn><mo>=</mo><mn>2.820</mn></mrow></semantics></math> Å，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>=</mo><mn>1.5406</mn><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mn>2</mn><mo>×</mo><mn>2.820</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>0.2732</mn></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>θ</mi><mo>=</mo><mn>15.85</mn><mi mathvariant=\"normal\">°</mi></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2</mn><mi>θ</mi><mo>=</mo><mn>31.70</mn><mi mathvariant=\"normal\">°</mi></mrow></semantics></math>。","(b) 岩盐是面心格子，(100) 的 h、k、l 有奇有偶，四个面心位置的贡献正好抵消，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>F</mi><mn>100</mn></msub><mo>=</mo><mn>0</mn></mrow></semantics></math>。","(c) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>β</mi><mo>=</mo><mn>0.9</mn><mo>×</mo><mn>1.5406</mn><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mn>200</mn><mtext> </mtext><mover accent=\"true\"><mtext>A</mtext><mo>˚</mo></mover><mo>×</mo><mi>cos</mi><mo>⁡</mo><mn>15.85</mn><mi mathvariant=\"normal\">°</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mn>7.21</mn><mo>×</mo><mn>1</mn><msup><mn>0</mn><mrow><mo>−</mo><mn>3</mn></mrow></msup></mrow></semantics></math> rad <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>=</mo><mn>0.41</mn><mi mathvariant=\"normal\">°</mi></mrow></semantics></math>。"],"a":"在粉末衍射演示里选氯化钠、把晶粒调到 20 nm，峰表里的 (200) 就在 31.70°，读数里有第一个峰的 Scherrer 宽度。实验室衍射仪的仪器展宽通常在 0.05–0.1°，比这个小，所以 20 nm 的晶粒很容易从峰宽看出来。"},"cites":"<a href=\"#ref-bragg1913\" data-ref=\"bragg1913\">Bragg &amp; Bragg 1913</a> · <a href=\"#ref-laue1913\" data-ref=\"laue1913\">Friedrich, Knipping &amp; Laue 1913</a> · <a href=\"#ref-patterson1934\" data-ref=\"patterson1934\">Patterson 1934</a> · <a href=\"#ref-patterson1939\" data-ref=\"patterson1939\">Patterson 1939</a> · <a href=\"#ref-franklin1953\" data-ref=\"franklin1953\">Franklin &amp; Gosling 1953</a> · <a href=\"#ref-kendrew1958\" data-ref=\"kendrew1958\">Kendrew et al. 1958</a> · <a href=\"#ref-rietveld1969\" data-ref=\"rietveld1969\">Rietveld 1969</a> · <a href=\"#ref-shechtman1984\" data-ref=\"shechtman1984\">Shechtman et al. 1984</a> · <a href=\"#ref-miao1999\" data-ref=\"miao1999\">Miao et al. 1999</a> · <a href=\"#ref-neutze2000\" data-ref=\"neutze2000\">Neutze et al. 2000</a> · <a href=\"#ref-chapman2011\" data-ref=\"chapman2011\">Chapman et al. 2011</a>"},"polarization":{"id":"polarization","body":[{"p":"前五章只用了一个标量的“波的大小”。这已经够解释干涉和衍射，但漏掉了一件事：光的电场是一个矢量，垂直于传播方向。沿 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z</mi></mrow></semantics></math> 走的光，电场可以在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>x</mi></mrow></semantics></math> 方向振动，也可以在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y</mi></mrow></semantics></math> 方向，或者两者的任意组合。这个“朝哪个方向振动”就是偏振。声波是纵波，没有偏振；光有，这本身就证明光是横波。"},{"h":"界面上：菲涅耳公式"},{"p":"光从折射率 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mn>1</mn></msub></mrow></semantics></math> 的介质射到 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mn>2</mn></msub></mrow></semantics></math> 的介质，入射面由入射光线和界面法线决定。电场垂直于入射面的叫 s 分量，在入射面里的叫 p 分量。麦克斯韦方程要求电场和磁场的切向分量在界面上连续，由此得到两组反射振幅，也就是菲涅耳公式。正入射时两者相同，空气到玻璃（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>=</mo><mn>1.5</mn></mrow></semantics></math>）反射 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>n</mi><mo>+</mo><mn>1</mn><mo stretchy=\"false\">)</mo><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mo>=</mo><mn>4</mn><mi mathvariant=\"normal\">%</mi></mrow></semantics></math>；斜入射时 s 分量反射得越来越多，p 分量却先减小，在某个角度上降到零。"},{"p":"那个角度是布儒斯特角 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>tan</mi><mo>⁡</mo><msub><mi>θ</mi><mi>B</mi></msub><mo>=</mo><msub><mi>n</mi><mn>2</mn></msub><mi mathvariant=\"normal\">/</mi><msub><mi>n</mi><mn>1</mn></msub></mrow></semantics></math>，空气到玻璃是 56.3°，空气到水是 53.1°。1815 年 Brewster 从实验里总结出它 <span class=\"chm-cites\">[<a href=\"#ref-brewster1815\" data-ref=\"brewster1815\">Brewster 1815</a>]</span>。几何上的解释是：这时折射光线和反射方向正好垂直，介质里被激发振动的电偶极子沿着反射方向，而偶极子不向自己的轴向辐射。所以在布儒斯特角附近，水面和路面的反光几乎全是水平偏振的，偏振太阳镜只让竖直偏振通过，就把它挡掉了。摄影师的偏振镜、激光管两端斜放的布儒斯特窗用的都是这个。"},{"p":"反过来从光密射向光疏（玻璃到空气），入射角超过临界角 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mi>c</mi></msub><mo>=</mo><msub><mi>n</mi><mn>2</mn></msub><mi mathvariant=\"normal\">/</mi><msub><mi>n</mi><mn>1</mn></msub></mrow></semantics></math>（玻璃 41.8°）时没有折射光，全部反射。这就是光纤能把光困在纤芯里传几十公里的原因（第七章）。全反射时界面另一侧仍有一个沿表面传、向外指数衰减的倏逝波，深度约一个波长；全内反射荧光显微镜（TIRF）、衰减全反射红外（ATR）和表面等离激元传感器都只看这一薄层。"},{"demo":"reflect"},{"h":"Jones 矢量：偏振的代数"},{"p":"单色、完全偏振的光可以写成两个复数 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\">(</mo><msub><mi>E</mi><mi>x</mi></msub><mo separator=\"true\">,</mo><msub><mi>E</mi><mi>y</mi></msub><mo stretchy=\"false\">)</mo></mrow></semantics></math>，它们的模是两个方向上的振幅，辐角之差是两个分量的相位差。相位差为 0 或 π 时电场在一条线上来回，叫线偏振；相位差为 ±π/2 且振幅相等时电场的端点画圆，叫圆偏振；其他情况是椭圆偏振。1941 年 Jones 把每个光学元件写成一个 2 × 2 矩阵 <span class=\"chm-cites\">[<a href=\"#ref-jones1941\" data-ref=\"jones1941\">Jones 1941</a>]</span>：偏振片是投影，波片在快轴和慢轴之间引入一个固定的相位差（四分之一波片 π/2，半波片 π），一串元件就是矩阵连乘。"},{"p":"最好玩的结论是“三片偏振片”：两片正交的偏振片把光全挡住，在它们中间插第三片 45° 的偏振片，反而透过 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mn>1</mn><mn>2</mn></mfrac><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mn>45</mn><mi mathvariant=\"normal\">°</mi><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mn>45</mn><mi mathvariant=\"normal\">°</mi><mo>=</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mn>8</mn></mrow></semantics></math>。中间那片不是“放行”了什么，而是把偏振重新投影到一个新的方向上。马吕斯定律 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>I</mi><mo>=</mo><msub><mi>I</mi><mn>0</mn></msub><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mi>θ</mi></mrow></semantics></math> 只是投影的平方。部分偏振和自然光要用 Stokes 参数或 Mueller 矩阵，Jones 矢量只描述完全偏振的光。"},{"demo":"jones"},{"h":"双折射"},{"p":"方解石、石英、液晶和拉伸的塑料对不同偏振的光有不同的折射率，叫双折射。透过方解石看字会看到两个像；两片正交偏振片之间夹一块受力的塑料尺，会看到彩色的应力条纹（光弹性），工程上用它看零件里的应力分布。波片就是切成特定厚度的双折射晶体，让两个偏振分量的光程差恰好是 λ/4 或 λ/2。液晶显示器里每个像素是一个能用电压调节的波片，夹在两片偏振片之间：调电压就是调亮度。"},{"h":"手性：旋光和圆二色"},{"p":"线偏振可以看成等量的左旋和右旋圆偏振之和。手性分子（和它的镜像不能重合）对左右圆偏振的折射率略有不同，两个分量走过样品后相位差变了，合成的线偏振就转过一个角度：这是旋光，Pasteur 1848 年正是靠它把酒石酸的两种镜像晶体分开的。如果分子对左右圆偏振的吸收不同，就是圆二色（CD）：蛋白质的 α 螺旋在 208 nm 和 222 nm 有两个负峰，β 折叠在 218 nm 附近有一个，所以 CD 谱是估计蛋白质二级结构最快的办法。谱图馆的<a href=\"../spectra/#m-cd\">圆二色</a>和<a href=\"../spectra/#m-polarimetry\">旋光</a>两种方法讲读谱。"},{"h":"天空的蓝色和偏振"},{"p":"比波长小得多的粒子（空气分子）被光的电场推动，成为振动的偶极子，向四周辐射。偶极辐射的功率正比于频率的四次方，所以散射光强 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∝</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><msup><mi>λ</mi><mn>4</mn></msup></mrow></semantics></math>：蓝光（450 nm）比红光（700 nm）散射得多约 5.9 倍，天空是蓝的，落日是红的。Rayleigh 1871 年用这个解释了天空的颜色 <span class=\"chm-cites\">[<a href=\"#ref-rayleigh1871\" data-ref=\"rayleigh1871\">Rayleigh 1871</a>]</span>。偶极子不向自己的轴向辐射，所以和太阳成 90° 的方向上天光强烈地偏振（理想情况可达 100 %，实际约 70 %），蜜蜂和一些鸟能看到这种偏振并用来导航。"},{"p":"粒子和波长差不多大时，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><msup><mi>λ</mi><mn>4</mn></msup></mrow></semantics></math> 不再成立，要解球形粒子的完整麦克斯韦方程，这是 Mie 1908 年为解释胶体金的颜色做的 <span class=\"chm-cites\">[<a href=\"#ref-mie1908\" data-ref=\"mie1908\">Mie 1908</a>]</span>。云滴有几微米，各种颜色散射得差不多，所以云是白的；金纳米颗粒的局域表面等离激元让它在 520 nm 附近强烈吸收，溶液是酒红色的。动态光散射（DLS）从散射光强的涨落测粒径，原理见谱图馆的<a href=\"../spectra/#m-dls\">动态光散射</a>。"}],"points":[{"h":"偏振证明光是横波","p":"电场垂直于传播方向；s 和 p 是相对入射面的两个分量。","st":"proved"},{"h":"正入射反射 ((n − 1)/(n + 1))²","p":"玻璃 4 %，水 2 %，金刚石 17 %；一块没镀膜的透镜每个面都损失这么多。","st":"proved"},{"h":"布儒斯特角 tan θ_B = n₂/n₁","p":"p 偏振完全不反射；水面反光因此是水平偏振的。","st":"tested"},{"h":"全反射和倏逝波","p":"超过临界角全部反射，但界面外有约一个波长深的倏逝场；TIRF、ATR 靠它。","st":"proved"},{"h":"三片偏振片透过 1/8","p":"偏振片是投影；Jones 矩阵连乘就能算任何一串理想元件。","st":"proved"},{"h":"旋光和圆二色看手性","p":"左右圆偏振的折射率或吸收不同；CD 谱估计蛋白质二级结构。","st":"tested"},{"h":"Rayleigh 散射 ∝ 1/λ⁴","p":"只对远小于波长的粒子成立；粒子变大就要用 Mie 理论。","st":"approx"}],"math":[{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>r</mi><mi>s</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>n</mi><mn>1</mn></msub><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>i</mi></msub><mo>−</mo><msub><mi>n</mi><mn>2</mn></msub><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>t</mi></msub></mrow><mrow><msub><mi>n</mi><mn>1</mn></msub><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>i</mi></msub><mo>+</mo><msub><mi>n</mi><mn>2</mn></msub><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>t</mi></msub></mrow></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>r</mi><mi>p</mi></msub><mo>=</mo><mfrac><mrow><msub><mi>n</mi><mn>2</mn></msub><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>i</mi></msub><mo>−</mo><msub><mi>n</mi><mn>1</mn></msub><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>t</mi></msub></mrow><mrow><msub><mi>n</mi><mn>2</mn></msub><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>i</mi></msub><mo>+</mo><msub><mi>n</mi><mn>1</mn></msub><mi>cos</mi><mo>⁡</mo><msub><mi>θ</mi><mi>t</mi></msub></mrow></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>R</mi><mo>=</mo><mi mathvariant=\"normal\">∣</mi><mi>r</mi><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup></mrow></semantics></math>","cap":"菲涅耳公式（非磁性介质），θ_t 由斯涅尔定律给出。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>tan</mi><mo>⁡</mo><msub><mi>θ</mi><mi>B</mi></msub><mo>=</mo><mfrac><msub><mi>n</mi><mn>2</mn></msub><msub><mi>n</mi><mn>1</mn></msub></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mi>c</mi></msub><mo>=</mo><mfrac><msub><mi>n</mi><mn>2</mn></msub><msub><mi>n</mi><mn>1</mn></msub></mfrac><mtext> </mtext><mo stretchy=\"false\">(</mo><msub><mi>n</mi><mn>1</mn></msub><mo>&gt;</mo><msub><mi>n</mi><mn>2</mn></msub><mo stretchy=\"false\">)</mo></mrow></semantics></math>","cap":"布儒斯特角和临界角。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>P</mi><mo stretchy=\"false\">(</mo><mi>θ</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mrow><mo fence=\"true\">(</mo><mtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mi>θ</mi></mrow></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mi>cos</mi><mo>⁡</mo><mi>θ</mi></mrow></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mi>cos</mi><mo>⁡</mo><mi>θ</mi></mrow></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><msup><mrow><mi>sin</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mi>θ</mi></mrow></mstyle></mtd></mtr></mtable><mo fence=\"true\">)</mo></mrow><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>W</mi><mo stretchy=\"false\">(</mo><mi>θ</mi><mo separator=\"true\">,</mo><mi mathvariant=\"normal\">Γ</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mi>R</mi><mo stretchy=\"false\">(</mo><mi>θ</mi><mo stretchy=\"false\">)</mo><mrow><mo fence=\"true\">(</mo><mtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>1</mn></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0</mn></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0</mn></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msup><mi>e</mi><mrow><mi>i</mi><mi mathvariant=\"normal\">Γ</mi></mrow></msup></mstyle></mtd></mtr></mtable><mo fence=\"true\">)</mo></mrow><mi>R</mi><mo stretchy=\"false\">(</mo><mo>−</mo><mi>θ</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math>","cap":"Jones 矩阵：轴在 θ 的偏振片，快轴在 θ、延迟 Γ 的波片（Γ = π/2 四分之一波片，π 半波片）<span class=\"chm-cites\">[<a href=\"#ref-jones1941\" data-ref=\"jones1941\">Jones 1941</a>]</span>。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><msub><mi>I</mi><mn>0</mn></msub><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mi>θ</mi></mrow></semantics></math>","cap":"马吕斯定律。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>I</mi><mrow><mi mathvariant=\"normal\">s</mi><mi mathvariant=\"normal\">c</mi><mi mathvariant=\"normal\">a</mi><mi mathvariant=\"normal\">t</mi></mrow></msub><mo>∝</mo><mfrac><msup><mi>α</mi><mn>2</mn></msup><msup><mi>λ</mi><mn>4</mn></msup></mfrac><mtext> </mtext><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><msup><mrow><mi>cos</mi><mo>⁡</mo></mrow><mn>2</mn></msup><mi mathvariant=\"normal\">Θ</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math>","cap":"非偏振光的 Rayleigh 散射：α 是极化率，Θ 是散射角 <span class=\"chm-cites\">[<a href=\"#ref-rayleigh1871\" data-ref=\"rayleigh1871\">Rayleigh 1871</a>]</span>。"}],"example":{"q":"一束自然光从空气射到水面（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>=</mo><mn>1.333</mn></mrow></semantics></math>）。(a) 布儒斯特角是多少？(b) 正入射时反射多少？(c) 在布儒斯特角上，s 偏振反射多少？","steps":["(a) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mi>B</mi></msub><mo>=</mo><mi>arctan</mi><mo>⁡</mo><mn>1.333</mn><mo>=</mo><mn>53.12</mn><mi mathvariant=\"normal\">°</mi></mrow></semantics></math>。","(b) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>R</mi><mo>=</mo><mo stretchy=\"false\">(</mo><mn>0.333</mn><mi mathvariant=\"normal\">/</mi><mn>2.333</mn><msup><mo stretchy=\"false\">)</mo><mn>2</mn></msup><mo>=</mo><mn>2.04</mn><mi mathvariant=\"normal\">%</mi></mrow></semantics></math>。","(c) 在布儒斯特角上 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>θ</mi><mi>t</mi></msub><mo>=</mo><mn>90</mn><mi mathvariant=\"normal\">°</mi><mo>−</mo><msub><mi>θ</mi><mi>B</mi></msub><mo>=</mo><mn>36.88</mn><mi mathvariant=\"normal\">°</mi></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>r</mi><mi>s</mi></msub><mo>=</mo><mo stretchy=\"false\">(</mo><mi>cos</mi><mo>⁡</mo><mn>53.12</mn><mi mathvariant=\"normal\">°</mi><mo>−</mo><mn>1.333</mn><mi>cos</mi><mo>⁡</mo><mn>36.88</mn><mi mathvariant=\"normal\">°</mi><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>cos</mi><mo>⁡</mo><mn>53.12</mn><mi mathvariant=\"normal\">°</mi><mo>+</mo><mn>1.333</mn><mi>cos</mi><mo>⁡</mo><mn>36.88</mn><mi mathvariant=\"normal\">°</mi><mo stretchy=\"false\">)</mo><mo>=</mo><mo stretchy=\"false\">(</mo><mn>0.600</mn><mo>−</mo><mn>1.066</mn><mo stretchy=\"false\">)</mo><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mn>0.600</mn><mo>+</mo><mn>1.066</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mo>−</mo><mn>0.280</mn></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>s</mi></msub><mo>=</mo><mn>7.8</mn><mi mathvariant=\"normal\">%</mi></mrow></semantics></math>，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R</mi><mi>p</mi></msub><mo>=</mo><mn>0</mn></mrow></semantics></math>。"],"a":"自然光里反射回来的约 3.9 %（7.8 % 的一半）全是水平偏振的。在菲涅耳公式演示里选“空气 → 水”、按“布儒斯特角”就能看到。"},"cites":"<a href=\"#ref-brewster1815\" data-ref=\"brewster1815\">Brewster 1815</a> · <a href=\"#ref-rayleigh1871\" data-ref=\"rayleigh1871\">Rayleigh 1871</a> · <a href=\"#ref-mie1908\" data-ref=\"mie1908\">Mie 1908</a> · <a href=\"#ref-jones1941\" data-ref=\"jones1941\">Jones 1941</a>"},"geometric":{"id":"geometric","body":[{"p":"前面几章一直在说“光是波”。可是日常里，阳光从窗缝照进来是一条直直的光柱，眼镜、相机、显微镜也都是按光线设计的。两者并不矛盾：当所有障碍物和开口都比波长大得多时，衍射的角度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>a</mi></mrow></semantics></math> 趋于零，波前上每一小块各走各的，沿着垂直于波前的方向前进，这条路径就是光线。几何光学是波动光学在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mo>→</mo><mn>0</mn></mrow></semantics></math> 时的极限，就像经典力学是量子力学在 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">ℏ</mi><mo>→</mo><mn>0</mn></mrow></semantics></math> 时的极限一样（数学上是同一套程序，叫程函近似或 WKB 近似）。"},{"h":"费马原理和斯涅尔定律"},{"p":"费马原理说，光从一点到另一点走的路径，让光程 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>∫</mo><mi>n</mi><mtext> </mtext><mi>d</mi><mi>s</mi></mrow></semantics></math> 取驻值（通常是最小）。在均匀介质里这就是直线；在两种介质的界面上，它给出斯涅尔定律 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n</mi><mn>1</mn></msub><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mn>1</mn></msub><mo>=</mo><msub><mi>n</mi><mn>2</mn></msub><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mn>2</mn></msub></mrow></semantics></math>：光在光密介质里走得慢，就宁可在里面少走一点。从波的角度看，费马原理说的正是第一章的道理：只有光程取驻值的那条路附近，邻近路径的相位才差不多，子波才相长叠加；其他路径的贡献互相抵消。"},{"h":"透镜和成像"},{"p":"一块凸透镜让平行光会聚到焦点。在傍轴近似（光线和光轴的夹角很小，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>≈</mo><mi>θ</mi></mrow></semantics></math>）下，物距 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>o</mi></msub></mrow></semantics></math>、像距 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>s</mi><mi>i</mi></msub></mrow></semantics></math> 和焦距 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f</mi></mrow></semantics></math> 满足 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><msub><mi>s</mi><mi>o</mi></msub><mo>+</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><msub><mi>s</mi><mi>i</mi></msub><mo>=</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>f</mi></mrow></semantics></math>，薄透镜的焦距由两个面的曲率半径和折射率决定（磨镜者公式）。这套傍轴理论（也叫高斯光学）可以写成 2 × 2 的光线传递矩阵，一串透镜就是矩阵连乘，和上一章的 Jones 矩阵形式上一模一样。"},{"p":"可是真实的光线并不都靠近光轴。对每条光线逐面精确地用斯涅尔定律（光线追迹），就会发现球面透镜聚不到一个点：离轴越远的光线，焦点离透镜越近，这叫球差。它和 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>h</mi><mn>2</mn></msup></mrow></semantics></math> 成正比（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>h</mi></mrow></semantics></math> 是光线高度），所以光圈缩小一半，纵向球差就小到四分之一。下面的演示精确追迹每一条光线。同一块平凸透镜，凸面朝向平行光时两个面分担了偏折，球差比平面朝光时小约四倍；这是摄影和望远镜里“透镜怎么摆”的第一条经验。"},{"demo":"lens"},{"p":"球差只是 Seidel 归纳的五种单色像差之一，另外四种是彗差、像散、场曲和畸变。折射率还随波长变（色散），所以蓝光的焦距比红光短，叫色差；把一块冕牌玻璃的凸透镜和一块火石玻璃的凹透镜粘在一起（消色差双胶合），可以让两种颜色聚到同一点。现代的显微物镜和相机镜头有十几片透镜，都是用计算机追迹几百万条光线优化出来的。非球面透镜（今天用模压或金刚石车削制造）可以在一个面上消掉球差。"},{"h":"数值孔径：几何和波动的接头"},{"p":"一个物镜能接住的光锥半角为 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>α</mi></mrow></semantics></math>，数值孔径定义为 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mo>=</mo><mi>n</mi><mi>sin</mi><mo>⁡</mo><mi>α</mi></mrow></semantics></math>（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi></mrow></semantics></math> 是物和物镜之间介质的折射率）。NA 同时管两件事：收集多少光（亮度正比于 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mn>2</mn></msup></mrow></semantics></math>），和能分辨多细的结构（分辨率约 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0.61</mn><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow></mrow></semantics></math>，第三章的艾里斑）。干物镜的 NA 不会超过 1；在样品和物镜之间滴上浸油（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>=</mo><mn>1.52</mn></mrow></semantics></math>），NA 可以做到 1.4 以上，这是油镜的意义。像差都校正好、只受衍射限制的系统叫“衍射极限”系统：几何光学设计到这一步就到头了，再往下得看第八章的波动光学。"},{"h":"光纤"},{"p":"光纤的纤芯折射率比包层稍高，以小角度射进去的光在芯和包层的界面上不断全反射，就被困在纤芯里。1966 年高锟和 Hockham 分析指出，当时玻璃里每公里上千 dB 的损耗主要来自杂质而不是玻璃本身，如果把杂质降下来，损耗可以低到每公里 20 dB 以下，光纤就能用来通信 <span class=\"chm-cites\">[<a href=\"#ref-kao1966\" data-ref=\"kao1966\">Kao &amp; Hockham 1966</a>]</span>。几年后康宁公司做到了；今天的石英光纤在 1550 nm 的损耗约 0.2 dB/km，接近 Rayleigh 散射（第六章）设下的下限。高锟因此获得 2009 年诺贝尔物理学奖。"},{"h":"光镊：用光抓东西"},{"p":"光有动量，光线在透明小球里折射时改变了方向，小球就受到反作用力。用高 NA 物镜把激光聚成一个很尖的焦点时，折射率比周围高的小球会被拉向光最强的地方，稳稳地悬在焦点附近。1986 年 Ashkin 等人用单束激光实现了这种三维稳定的光学捕获 <span class=\"chm-cites\">[<a href=\"#ref-ashkin1986\" data-ref=\"ashkin1986\">Ashkin et al. 1986</a>]</span>，后来用它抓住活的细菌和病毒，测出驱动蛋白每一步走 8 nm、产生几皮牛的力。Ashkin 因此获得 2018 年诺贝尔物理学奖。对比波长大的小球，力可以用光线追迹算；比波长小的粒子则要按偶极子在电场梯度里的受力来算，这又是几何和波动两种图像的分界。"}],"points":[{"h":"几何光学是 λ → 0 的极限","p":"障碍物远大于波长时成立；在焦点、阴影边缘和小开口附近失效。","st":"approx"},{"h":"费马原理 ⇔ 斯涅尔定律","p":"光程取驻值；从波的角度看，是驻相路径附近的子波相长叠加。","st":"proved"},{"h":"球差 ∝ h²","p":"同一块平凸透镜凸面朝平行光时球差小约四倍。","st":"proved"},{"h":"NA 同时管亮度和分辨率","p":"NA = n sin α；油镜能做到 1.4 以上。","st":"tested"},{"h":"光纤：杂质才是损耗的主因","p":"1966 年的预言，今天约 0.2 dB/km，接近 Rayleigh 散射的下限。","st":"tested"},{"h":"光镊用光的动量抓住粒子","p":"单束高度聚焦的激光就能三维稳定地捕获；测出了分子马达的步长和力。","st":"tested"}],"math":[{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>δ</mi><mtext> ⁣</mtext><msubsup><mo>∫</mo><mi>A</mi><mi>B</mi></msubsup><mi>n</mi><mo stretchy=\"false\">(</mo><mi mathvariant=\"bold\">r</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><mi>d</mi><mi>s</mi><mo>=</mo><mn>0</mn><mspace width=\"1em\"/><mo>⟹</mo><mspace width=\"1em\"/><msub><mi>n</mi><mn>1</mn></msub><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mn>1</mn></msub><mo>=</mo><msub><mi>n</mi><mn>2</mn></msub><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mn>2</mn></msub></mrow></semantics></math>","cap":"费马原理和斯涅尔定律。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mfrac><mn>1</mn><msub><mi>s</mi><mi>o</mi></msub></mfrac><mo>+</mo><mfrac><mn>1</mn><msub><mi>s</mi><mi>i</mi></msub></mfrac><mo>=</mo><mfrac><mn>1</mn><mi>f</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mfrac><mn>1</mn><mi>f</mi></mfrac><mo>=</mo><mo stretchy=\"false\">(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mrow><mo fence=\"true\">(</mo><mfrac><mn>1</mn><msub><mi>R</mi><mn>1</mn></msub></mfrac><mo>−</mo><mfrac><mn>1</mn><msub><mi>R</mi><mn>2</mn></msub></mfrac><mo fence=\"true\">)</mo></mrow></mrow></semantics></math>","cap":"薄透镜的成像公式和磨镜者公式（傍轴、空气中）。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mrow><mo fence=\"true\">(</mo><mtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msup><mi>y</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><msup><mi>u</mi><mo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′</mo></msup></mstyle></mtd></mtr></mtable><mo fence=\"true\">)</mo></mrow><mo>=</mo><mrow><mo fence=\"true\">(</mo><mtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>1</mn></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0</mn></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mrow><mo>−</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>f</mi></mrow></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>1</mn></mstyle></mtd></mtr></mtable><mo fence=\"true\">)</mo></mrow><mrow><mo fence=\"true\">(</mo><mtable rowspacing=\"0.16em\" columnalign=\"center center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>1</mn></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mi>d</mi></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>0</mn></mstyle></mtd><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mn>1</mn></mstyle></mtd></mtr></mtable><mo fence=\"true\">)</mo></mrow><mrow><mo fence=\"true\">(</mo><mtable rowspacing=\"0.16em\" columnalign=\"center\" columnspacing=\"1em\"><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mi>y</mi></mstyle></mtd></mtr><mtr><mtd><mstyle scriptlevel=\"0\" displaystyle=\"false\"><mi>u</mi></mstyle></mtd></mtr></mtable><mo fence=\"true\">)</mo></mrow></mrow></semantics></math>","cap":"光线传递矩阵：先走距离 d，再过焦距 f 的薄透镜（y 是高度，u 是角度）。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mo>=</mo><mi>n</mi><mi>sin</mi><mo>⁡</mo><mi>α</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>θ</mi><mi>max</mi><mo>⁡</mo></msub><mo>=</mo><mi>arcsin</mi><mo>⁡</mo><msqrt><mrow><msubsup><mi>n</mi><mrow><mi mathvariant=\"normal\">c</mi><mi mathvariant=\"normal\">o</mi><mi mathvariant=\"normal\">r</mi><mi mathvariant=\"normal\">e</mi></mrow><mn>2</mn></msubsup><mo>−</mo><msubsup><mi>n</mi><mrow><mi mathvariant=\"normal\">c</mi><mi mathvariant=\"normal\">l</mi><mi mathvariant=\"normal\">a</mi><mi mathvariant=\"normal\">d</mi></mrow><mn>2</mn></msubsup></mrow></msqrt></mrow></semantics></math>","cap":"数值孔径；光纤的接收角。"}],"example":{"q":"一块平凸透镜，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>=</mo><mn>1.5168</mn></mrow></semantics></math>（BK7），曲率半径 50 mm。(a) 薄透镜近似下焦距多少？(b) 一根纤芯 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>=</mo><mn>1.468</mn></mrow></semantics></math>、包层 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n</mi><mo>=</mo><mn>1.462</mn></mrow></semantics></math> 的单模光纤，数值孔径和接收角多少？","steps":["(a) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1</mn><mi mathvariant=\"normal\">/</mi><mi>f</mi><mo>=</mo><mo stretchy=\"false\">(</mo><mn>1.5168</mn><mo>−</mo><mn>1</mn><mo stretchy=\"false\">)</mo><mo stretchy=\"false\">(</mo><mn>1</mn><mi mathvariant=\"normal\">/</mi><mn>50</mn><mo>−</mo><mn>0</mn><mo stretchy=\"false\">)</mo><mo>=</mo><mn>0.010336</mn></mrow></semantics></math> mm⁻¹，<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f</mi><mo>=</mo><mn>96.75</mn></mrow></semantics></math> mm。","(b) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mo>=</mo><msqrt><mrow><mn>1.46</mn><msup><mn>8</mn><mn>2</mn></msup><mo>−</mo><mn>1.46</mn><msup><mn>2</mn><mn>2</mn></msup></mrow></msqrt><mo>=</mo><msqrt><mn>0.017580</mn></msqrt><mo>=</mo><mn>0.1326</mn></mrow></semantics></math>，接收角 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>arcsin</mi><mo>⁡</mo><mn>0.1326</mn><mo>=</mo><mn>7.6</mn><mi mathvariant=\"normal\">°</mi></mrow></semantics></math>。"],"a":"光线追迹演示的读数里有磨镜者公式给出的 96.75 mm；8 mm 厚的真实透镜的傍轴焦点（从第一面顶点量）会比它略远一些，边缘光线则明显更近，那就是球差。"},"cites":"<a href=\"#ref-kao1966\" data-ref=\"kao1966\">Kao &amp; Hockham 1966</a> · <a href=\"#ref-ashkin1986\" data-ref=\"ashkin1986\">Ashkin et al. 1986</a>"},"fourier":{"id":"fourier","body":[{"p":"第三章说过，夫琅禾费衍射图样就是开口的傅里叶变换，只不过要在“无穷远”才看得到。一块会聚透镜把无穷远搬到了它的后焦面上：物放在透镜前焦面，后焦面上的光场正好是物的傅里叶变换，每一点对应一个空间频率 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f</mi><mo>=</mo><mi>x</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>λ</mi><mi>F</mi><mo stretchy=\"false\">)</mo></mrow></semantics></math>（<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>F</mi></mrow></semantics></math> 是焦距）。再用第二块透镜做一次变换，就得到像。这叫 4f 系统，是傅里叶光学的基本装置：在两块透镜中间的那个面上动手脚，就能挑选像里保留哪些空间频率。"},{"h":"Abbe：显微镜为什么有极限"},{"p":"1873 年 Abbe 在蔡司工作时提出，显微镜的像要分两步理解 <span class=\"chm-cites\">[<a href=\"#ref-abbe1873\" data-ref=\"abbe1873\">Abbe 1873</a>]</span>。物（比如一个周期为 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p</mi></mrow></semantics></math> 的光栅）先把照明光衍射成零级、±1 级、±2 级……，各级的角度 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mi>m</mi></msub><mo>=</mo><mi>m</mi><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>p</mi></mrow></semantics></math>；物镜只能接住 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><mi>θ</mi><mo>≤</mo><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow></mrow></semantics></math> 的那几级；像是由接住的这几级重新干涉出来的。如果只接住零级，像里就只有一片均匀的亮，条纹完全消失；至少要接住零级和一个一级，才有条纹。所以相干照明、正入射时能分辨的最小周期是 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow></mrow></semantics></math>，斜照明能改善到 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mn>2</mn><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mo stretchy=\"false\">)</mo></mrow></semantics></math>。这就是显微镜的分辨率极限：不是透镜磨得不好，而是那些携带细节的衍射光根本没有进物镜。"},{"demo":"abbe"},{"h":"看见透明的东西：暗场和相衬"},{"p":"活细胞几乎是透明的，它只让光的相位变一点（厚的地方光程多一点），振幅几乎不变。眼睛和相机只看强度，所以普通显微镜里它几乎看不见。如果在后焦面上挡住零级（暗场），背景变黑，只有散射光成像，边缘就亮起来。Zernike 想得更巧：对弱相位物 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e</mi><mrow><mi>i</mi><mi>ϕ</mi></mrow></msup><mo>≈</mo><mn>1</mn><mo>+</mo><mi>i</mi><mi>ϕ</mi></mrow></semantics></math>，散射光和零级之间正好差 90°，强度里没有一阶的 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ϕ</mi></mrow></semantics></math>；把零级的相位再推 90°（相位板），两部分就同相或反相，强度变成 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo>≈</mo><mn>1</mn><mo>±</mo><mn>2</mn><mi>ϕ</mi></mrow></semantics></math>，相位差直接变成了明暗 <span class=\"chm-cites\">[<a href=\"#ref-zernike1942\" data-ref=\"zernike1942\">Zernike 1942</a>]</span>。Zernike 因此获得 1953 年诺贝尔物理学奖。今天的生物实验室里，相衬和它的近亲微分干涉衬度（DIC）几乎每天都在用。"},{"h":"全息：把相位也记下来"},{"p":"照相底片只记录强度，丢掉相位，和第五章 X 射线衍射的相位问题是同一个麻烦。1948 年 Gabor 为改进电子显微镜想出一个办法：让物光和一束已知的参考光干涉，干涉条纹里就同时存下了物光的振幅和相位；用参考光再照一次底片，物光的波前就被重建出来 <span class=\"chm-cites\">[<a href=\"#ref-gabor1948\" data-ref=\"gabor1948\">Gabor 1948</a>]</span>。这就是全息术，在激光出现之后才真正好用（Gabor 1971 年获诺贝尔物理学奖）。今天的数字全息显微镜直接用相机记录干涉图，在计算机里做傅里叶变换重建相位。"},{"h":"快速傅里叶变换"},{"p":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi></mrow></semantics></math> 个采样点的离散傅里叶变换按定义要 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>N</mi><mn>2</mn></msup></mrow></semantics></math> 次乘法；1965 年 Cooley 和 Tukey 发表的算法只要约 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N</mi><msub><mrow><mi>log</mi><mo>⁡</mo></mrow><mn>2</mn></msub><mi>N</mi></mrow></semantics></math> 次 <span class=\"chm-cites\">[<a href=\"#ref-cooley1965\" data-ref=\"cooley1965\">Cooley &amp; Tukey 1965</a>]</span>，对一百万个点快了五万倍。没有它，傅里叶变换红外光谱（第二章）、核磁共振、数字全息、上面那个演示，乃至现在的大部分信号处理都无法实时进行。本栏目所有的演示在浏览器里都是现算的，阿贝成像那一个就是先对物做一次 FFT、在频域里挡掉一部分、再做一次逆 FFT。"},{"h":"绕过衍射极限：超分辨荧光显微镜"},{"p":"Abbe 的极限对“用透镜收集的光”是严格的。可是荧光显微镜看的不是散射光，而是分子自己发的光，而分子的开和关是可以控制的。1994 年 Hell 和 Wichmann 提出 STED：用一束环形的“受激辐射损耗”光把激发光斑外圈的分子强行压回基态，只留下中间一个远小于衍射极限的点发光 <span class=\"chm-cites\">[<a href=\"#ref-hell1994\" data-ref=\"hell1994\">Hell &amp; Wichmann 1994</a>]</span>。2006 年另一条路几乎同时出现：每次只让稀疏的几个分子随机亮起来，它们的像虽然都是衍射斑，但单个斑的中心可以定到几纳米，重复成千上万次再拼起来（PALM <span class=\"chm-cites\">[<a href=\"#ref-betzig2006\" data-ref=\"betzig2006\">Betzig et al. 2006</a>]</span>、STORM <span class=\"chm-cites\">[<a href=\"#ref-rust2006\" data-ref=\"rust2006\">Rust et al. 2006</a>]</span>）。两种办法都把分辨率推到 20 nm 左右，Betzig、Hell 和 Moerner 获 2014 年诺贝尔化学奖。它们没有推翻 Abbe：衍射斑还是那么大，绕过去的办法是让相邻分子不在同一时刻发光。"},{"h":"没有透镜的成像"},{"p":"X 射线几乎做不出好透镜。1999 年 Miao 等人证明，只要把一个孤立小物体的衍射图采样得足够密（比布拉格条件密至少一倍，叫过采样），就可以在“物体外面是空的”这个约束下，用迭代算法在实空间和频率空间之间来回投影，找回丢失的相位 <span class=\"chm-cites\">[<a href=\"#ref-miao1999\" data-ref=\"miao1999\">Miao et al. 1999</a>]</span>。这就是相干衍射成像，相当于用计算机代替了物镜。它和第五章的 X 射线自由电子激光结合，正在把成像推向单个纳米颗粒、病毒和细胞。"},{"h":"人造的光学材料"},{"p":"1987 年 Yablonovitch 和 John 分别提出，折射率周期性变化、周期和光的波长相当的结构，会像晶体对电子那样给光子造出能带和带隙：某个频率范围里的光在任何方向都不能传播 <span class=\"chm-cites\">[<a href=\"#ref-yablonovitch1987\" data-ref=\"yablonovitch1987\">Yablonovitch 1987</a>; <a href=\"#ref-john1987\" data-ref=\"john1987\">John 1987</a>]</span>。这就是光子晶体，第二章的布拉格反射镜是它的一维版本，蝴蝶和孔雀羽毛的结构色是大自然的版本。2000 年 Pendry 指出折射率为 −1 的材料能做成“完美透镜”，连倏逝波也能放大，原理上不受衍射极限 <span class=\"chm-cites\">[<a href=\"#ref-pendry2000\" data-ref=\"pendry2000\">Pendry 2000</a>]</span>；2001 年 Shelby 等人在微波波段用金属环和导线组成的超材料实验观察到负折射 <span class=\"chm-cites\">[<a href=\"#ref-shelby2001\" data-ref=\"shelby2001\">Shelby et al. 2001</a>]</span>。在可见光波段做低损耗的负折射材料至今仍很困难。"},{"p":"光还能带轨道角动量。1992 年 Allen 等人指出，波前呈螺旋状、相位按 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e</mi><mrow><mi>i</mi><mi mathvariant=\"normal\">ℓ</mi><mi>ϕ</mi></mrow></msup></mrow></semantics></math> 绕光轴变化的光束（拉盖尔–高斯模），每个光子带 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">ℓ</mi><mi mathvariant=\"normal\">ℏ</mi></mrow></semantics></math> 的轨道角动量，和自旋（圆偏振的 ±ħ）是两回事 <span class=\"chm-cites\">[<a href=\"#ref-allen1992\" data-ref=\"allen1992\">Allen et al. 1992</a>]</span>。这种“涡旋光”中心是暗的，能让光镊里的颗粒转起来，也被研究用来在一根光纤里多路传信息。光是一个个光子的那一面（光子计数、纠缠、HOM 效应），见量子物理展馆的<a href=\"../quantum/physics/#c-optics\">量子光学</a>一章。"},{"h":"还没解决的问题"},{"list":["可见光波段的低损耗负折射材料和真正的“完美透镜”还没有做出来；金属的吸收是主要障碍。","单个生物大分子的 X 射线成像（不用晶体）还在发展：信号太弱、样品取向随机、辐射损伤快，目前只在病毒和较大的颗粒上做到较低分辨率。","超分辨显微镜在活细胞里的速度、光毒性和标记密度之间仍要取舍，分辨率越高往往越慢、越伤细胞。","光子晶体和超表面能在多大程度上替代传统的块状透镜和棱镜（尤其是宽波段、高效率时），还没有定论。"]}],"points":[{"h":"透镜做傅里叶变换","p":"后焦面上是物的空间频谱；4f 系统可以在中间的平面上滤波。","st":"proved"},{"h":"Abbe 极限 λ/NA","p":"接不住一级衍射，就看不到那个周期；斜照明改善到 λ/(2NA)。","st":"proved"},{"h":"相衬把相位变成明暗","p":"零级移 90°，弱相位物的强度变成 1 ± 2φ。","st":"tested"},{"h":"全息记下振幅和相位","p":"和已知参考光干涉；数字全息在计算机里重建。","st":"tested"},{"h":"超分辨：不同时发光","p":"STED 压掉外圈，PALM/STORM 逐个定位；约 20 nm，Abbe 并没有被推翻。","st":"tested"},{"h":"过采样找回相位","p":"孤立物体的衍射图采得足够密，迭代算法就能找回相位。","st":"tested"},{"h":"光子晶体和超材料","p":"光子带隙在多个波段已实现；可见光的负折射仍受损耗限制。","st":"frontier"}],"math":[{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>U</mi><mi>f</mi></msub><mo stretchy=\"false\">(</mo><msub><mi>x</mi><mi>f</mi></msub><mo stretchy=\"false\">)</mo><mo>=</mo><mfrac><mn>1</mn><mrow><mi>i</mi><mi>λ</mi><mi>F</mi></mrow></mfrac><mo>∫</mo><msub><mi>U</mi><mn>0</mn></msub><mo stretchy=\"false\">(</mo><mi>x</mi><mo stretchy=\"false\">)</mo><mtext> </mtext><msup><mi>e</mi><mrow><mo>−</mo><mn>2</mn><mi>π</mi><mi>i</mi><mtext> </mtext><mi>x</mi><msub><mi>x</mi><mi>f</mi></msub><mi mathvariant=\"normal\">/</mi><mo stretchy=\"false\">(</mo><mi>λ</mi><mi>F</mi><mo stretchy=\"false\">)</mo></mrow></msup><mtext> </mtext><mi>d</mi><mi>x</mi><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>f</mi><mi>x</mi></msub><mo>=</mo><mfrac><msub><mi>x</mi><mi>f</mi></msub><mrow><mi>λ</mi><mi>F</mi></mrow></mfrac></mrow></semantics></math>","cap":"透镜后焦面上的场是前焦面上物的傅里叶变换（标量、傍轴）。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi mathvariant=\"normal\">∣</mi><msub><mi>f</mi><mi>x</mi></msub><mi mathvariant=\"normal\">∣</mi><mo>≤</mo><mfrac><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mi>λ</mi></mfrac><mo separator=\"true\">,</mo><mspace width=\"2em\"/><msub><mi>p</mi><mi>min</mi><mo>⁡</mo></msub><mo>=</mo><mfrac><mi>λ</mi><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow></mfrac><mtext> (coherent, normal)</mtext><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mfrac><mi>λ</mi><mrow><mn>2</mn><mtext> </mtext><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow></mrow></mfrac><mtext> (oblique)</mtext></mrow></semantics></math>","cap":"相干成像的截止频率和 Abbe 极限 <span class=\"chm-cites\">[<a href=\"#ref-abbe1873\" data-ref=\"abbe1873\">Abbe 1873</a>]</span>。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msup><mi>e</mi><mrow><mi>i</mi><mi>ϕ</mi></mrow></msup><mo>≈</mo><mn>1</mn><mo>+</mo><mi>i</mi><mi>ϕ</mi><mtext> </mtext><mover><mo stretchy=\"true\" minsize=\"3.0em\">→</mo><mpadded width=\"+0.6em\" lspace=\"0.3em\"><mrow><mtext> zero order</mtext><mo>×</mo><msup><mi>e</mi><mrow><mi>i</mi><mi>π</mi><mi mathvariant=\"normal\">/</mi><mn>2</mn></mrow></msup><mtext> </mtext></mrow></mpadded></mover><mtext> </mtext><mi>i</mi><mo stretchy=\"false\">(</mo><mn>1</mn><mo>+</mo><mi>ϕ</mi><mo stretchy=\"false\">)</mo><mo separator=\"true\">,</mo><mspace width=\"2em\"/><mi>I</mi><mo>≈</mo><mn>1</mn><mo>+</mo><mn>2</mn><mi>ϕ</mi></mrow></semantics></math>","cap":"Zernike 相衬：弱相位物的一阶项变成了强度 <span class=\"chm-cites\">[<a href=\"#ref-zernike1942\" data-ref=\"zernike1942\">Zernike 1942</a>]</span>。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><mi>I</mi><mo>=</mo><mi mathvariant=\"normal\">∣</mi><mi>O</mi><mo>+</mo><mi>R</mi><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup><mo>=</mo><mi mathvariant=\"normal\">∣</mi><mi>O</mi><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup><mo>+</mo><mi mathvariant=\"normal\">∣</mi><mi>R</mi><msup><mi mathvariant=\"normal\">∣</mi><mn>2</mn></msup><mo>+</mo><mi>O</mi><msup><mi>R</mi><mo>∗</mo></msup><mo>+</mo><msup><mi>O</mi><mo>∗</mo></msup><mi>R</mi></mrow></semantics></math>","cap":"全息：交叉项 O R* 同时存下物光的振幅和相位 <span class=\"chm-cites\">[<a href=\"#ref-gabor1948\" data-ref=\"gabor1948\">Gabor 1948</a>]</span>。"},{"m":"<math xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\"><semantics><mrow><msub><mi>σ</mi><mrow><mi mathvariant=\"normal\">l</mi><mi mathvariant=\"normal\">o</mi><mi mathvariant=\"normal\">c</mi></mrow></msub><mo>≈</mo><mfrac><mi>s</mi><msqrt><mi>N</mi></msqrt></mfrac></mrow></semantics></math>","cap":"单分子定位的精度：s 是衍射斑的宽度，N 是收集到的光子数（忽略背景和像素化）。"}],"example":{"q":"用绿光（550 nm）、NA = 0.4 的物镜、相干正入射照明。(a) 能分辨的最小光栅周期是多少？(b) 周期 1.2 μm 和 1.4 μm 的光栅各有几级衍射进得去？(c) 换成 NA = 1.4 的油镜呢？","steps":["(a) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>p</mi><mi>min</mi><mo>⁡</mo></msub><mo>=</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mrow><mi mathvariant=\"normal\">N</mi><mi mathvariant=\"normal\">A</mi></mrow><mo>=</mo><mn>0.55</mn><mi mathvariant=\"normal\">/</mi><mn>0.4</mn><mo>=</mo><mn>1.375</mn></mrow></semantics></math> μm。","(b) 一级的 <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>sin</mi><mo>⁡</mo><msub><mi>θ</mi><mn>1</mn></msub><mo>=</mo><mi>λ</mi><mi mathvariant=\"normal\">/</mi><mi>p</mi></mrow></semantics></math>：1.2 μm 时是 0.458 &gt; 0.4，进不去，像里没有条纹；1.4 μm 时是 0.393 &lt; 0.4，±1 级刚好进得去，条纹出现。","(c) <math xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0.55</mn><mi mathvariant=\"normal\">/</mi><mn>1.4</mn><mo>=</mo><mn>0.39</mn></mrow></semantics></math> μm，好了三倍半。"],"a":"阿贝成像演示里的两个预设按钮正是 (b) 的两种情况：读数里“通过的衍射级”从“只有零级”变成“0, ±1”，像的对比度从 0 跳上去。"},"cites":"<a href=\"#ref-abbe1873\" data-ref=\"abbe1873\">Abbe 1873</a> · <a href=\"#ref-zernike1942\" data-ref=\"zernike1942\">Zernike 1942</a> · <a href=\"#ref-gabor1948\" data-ref=\"gabor1948\">Gabor 1948</a> · <a href=\"#ref-cooley1965\" data-ref=\"cooley1965\">Cooley &amp; Tukey 1965</a> · <a href=\"#ref-john1987\" data-ref=\"john1987\">John 1987</a> · <a href=\"#ref-yablonovitch1987\" data-ref=\"yablonovitch1987\">Yablonovitch 1987</a> · <a href=\"#ref-allen1992\" data-ref=\"allen1992\">Allen et al. 1992</a> · <a href=\"#ref-hell1994\" data-ref=\"hell1994\">Hell &amp; Wichmann 1994</a> · <a href=\"#ref-miao1999\" data-ref=\"miao1999\">Miao et al. 1999</a> · <a href=\"#ref-pendry2000\" data-ref=\"pendry2000\">Pendry 2000</a> · <a href=\"#ref-shelby2001\" data-ref=\"shelby2001\">Shelby et al. 2001</a> · <a href=\"#ref-betzig2006\" data-ref=\"betzig2006\">Betzig et al. 2006</a> · <a href=\"#ref-rust2006\" data-ref=\"rust2006\">Rust et al. 2006</a>"}}};
